const BANK=[{"id": 0, "lesson": "Bài 1", "number": "1", "q": "Hãy cho biết đối tượng nghiên cứu môn học Giáo dục quốc phòng và an ninh là gì?", "a": "Đường lối quân sự của Đảng, công tác quốc phòng, an ninh và kỹ năng quân sự cần thiết.", "flag": false}, {"id": 1, "lesson": "Bài 1", "number": "2", "q": "Phương pháp luận chung nhất của việc nghiên cứu giáo dục quốc phòng và an ninh dựa trên cơ sở nào?", "a": "Học thuyết Mác - Lênin và tư tưởng Hồ Chí Minh.", "flag": false}, {"id": 2, "lesson": "Bài 1", "number": "3", "q": "Quá trình nghiên cứu môn học giáo dục quốc phòng và an ninh phải nắm vững và vận dụng đúng đắn các quan điểm nào sau đây?", "a": "Tiếp cận khoa học: Hệ thống, lịch sử, logic, thực tiễn.", "flag": false}, {"id": 3, "lesson": "Bài 1", "number": "4", "q": "Các phương pháp nghiên cứu môn học Giáo dục quốc phòng và an ninh?", "a": "Nghiên cứu lý thuyết, nghiên cứu thực tiễn, kết hợp các phương pháp dạy học lý thuyết và thực hành.", "flag": false}, {"id": 4, "lesson": "Bài 1", "number": "5", "q": "Theo Thông tư số 05/2020/TT-BGDĐT... chương trình môn học GDQPAN bao gồm mấy học phần?", "a": "04 học phần (HP1, HP2, HP3, HP4).", "flag": false}, {"id": 5, "lesson": "Bài 1", "number": "6", "q": "Theo Thông tư số 05/2020/TT-BGDĐT... tổng thời lượng bao nhiêu tiết?", "a": "165 tiết.", "flag": false}, {"id": 6, "lesson": "Bài 1", "number": "7", "q": "Theo Thông tư số 05/2020/TT-BGDĐT... học phần 1 - Đường lối quốc phòng và an ninh của Đảng Cộng sản Việt Nam là bao nhiêu tiết?", "a": "45 tiết.", "flag": false}, {"id": 7, "lesson": "Bài 1", "number": "8", "q": "Theo Thông tư số 05/2020/TT-BGDĐT... học phần 2 – Công tác quốc phòng và an ninh là bao nhiêu tiết?", "a": "30 tiết.", "flag": false}, {"id": 8, "lesson": "Bài 1", "number": "9", "q": "Theo Thông tư số 05/2020/TT-BGDĐT... học phần 3 – Quân sự chung là bao nhiêu tiết?", "a": "30 tiết.", "flag": false}, {"id": 9, "lesson": "Bài 1", "number": "10", "q": "Theo Thông tư số 05/2020/TT-BGDĐT... học phần 4 – Kỹ thuật chiến đấu bộ binh và chiến thuật là bao nhiêu tiết?", "a": "60 tiết.", "flag": false}, {"id": 10, "lesson": "Bài 1", "number": "11", "q": "Tên của học phần 1 chương trình giáo dục quốc phòng và an ninh theo Thông tư số 05/2020/TT-BGDĐT là?", "a": "Đường lối quốc phòng và an ninh của Đảng Cộng sản Việt Nam.", "flag": false}, {"id": 11, "lesson": "Bài 1", "number": "12", "q": "Tên của học phần 2 chương trình giáo dục quốc phòng và an ninh theo Thông tư số 05/2020/TT-BGDĐT là?", "a": "Công tác quốc phòng - an ninh.", "flag": false}, {"id": 12, "lesson": "Bài 1", "number": "13", "q": "Tên của học phần 3 chương trình giáo dục quốc phòng và an ninh theo Thông tư số 05/2020/TT-BGDĐT là?", "a": "Quân sự chung.", "flag": false}, {"id": 13, "lesson": "Bài 1", "number": "14", "q": "Tên của học phần 4 chương trình giáo dục quốc phòng và an ninh theo Thông tư số 05/2020/TT-BGDĐT là?", "a": "Kỹ năng chiến đấu bộ binh và chiến thuật.", "flag": false}, {"id": 14, "lesson": "Bài 1", "number": "15", "q": "Chương trình giáo dục quốc phòng và an ninh theo Thông tư số 05/2020/TT-BGDĐT, học phần 1 gồm bao nhiêu bài?", "a": "11 bài.", "flag": false}, {"id": 15, "lesson": "Bài 1", "number": "16", "q": "Chương trình giáo dục quốc phòng và an ninh theo Thông tư số 05/2020/TT-BGDĐT, học phần 2 gồm bao nhiêu bài?", "a": "07 bài.", "flag": false}, {"id": 16, "lesson": "Bài 1", "number": "17", "q": "Chương trình giáo dục quốc phòng và an ninh theo Thông tư số 05/2020/TT-BGDĐT, học phần 3 gồm bao nhiêu bài?", "a": "08 bài.", "flag": false}, {"id": 17, "lesson": "Bài 1", "number": "18", "q": "Chương trình giáo dục quốc phòng và an ninh theo Thông tư số 05/2020/TT-BGDĐT, học phần 4 gồm bao nhiêu bài?", "a": "05 bài.", "flag": false}, {"id": 18, "lesson": "Bài 1", "number": "19", "q": "Điều kiện để sinh viên được dự thi kết thúc học phần lần thứ nhất là gì?", "a": "Có mặt tối thiểu 80% thời lượng số tiết học phần; có đủ số lần kiểm tra và mỗi lần đạt từ 5 điểm trở lên.", "flag": false}, {"id": 19, "lesson": "Bài 1", "number": "20", "q": "Điều kiện đủ để sinh viên được cấp chứng chỉ Giáo dục quốc phòng và an ninh là?", "a": "Điểm trung bình chung GPA đạt từ 5,0 trở lên và tại thời điểm cấp chứng chỉ không bị truy cứu trách nhiệm hình sự.", "flag": false}, {"id": 20, "lesson": "Bài 1", "number": "21", "q": "Theo thông tư số 17/2021/TT-BGDĐT... quy đổi số tín chỉ Học phần 1 sang bao nhiêu tín chỉ?", "a": "3 tín chỉ.", "flag": false}, {"id": 21, "lesson": "Bài 1", "number": "22", "q": "Theo thông tư số 17/2021/TT-BGDĐT... quy đổi số tín chỉ Học phần 2 sang bao nhiêu tín chỉ?", "a": "2 tín chỉ.", "flag": false}, {"id": 22, "lesson": "Bài 1", "number": "23", "q": "Theo thông tư số 17/2021/TT-BGDĐT... quy đổi số tín chỉ Học phần 3 sang bao nhiêu tín chỉ?", "a": "2 tín chỉ (theo đáp án HP1.pdf) / 1 tín chỉ (theo TT 17).", "flag": true}, {"id": 23, "lesson": "Bài 1", "number": "24", "q": "Theo thông tư số 17/2021/TT-BGDĐT... quy đổi số tín chỉ Học phần 4 sang bao nhiêu tín chỉ?", "a": "4 tín chỉ (theo đáp án HP1.pdf) / 2 tín chỉ (theo TT 17).", "flag": true}, {"id": 24, "lesson": "Bài 1", "number": "25", "q": "Môn học Giáo dục quốc phòng và an ninh là:", "a": "Môn học luật định, bắt buộc trong chương trình đào tạo; giúp sinh viên hiểu đường lối QP-AN của Đảng, rèn luyện yêu nước và là điều kiện xét tốt nghiệp.", "flag": false}, {"id": 25, "lesson": "Bài 2", "number": "1", "q": "Theo quan điểm của chủ nghĩa Mác-Lênin nguồn gốc của chiến tranh là:", "a": "Sự xuất hiện và tồn tại của các giai cấp đối kháng trong xã hội.", "flag": false}, {"id": 26, "lesson": "Bài 2", "number": "2", "q": "Một trong những nguyên lý cơ bản của chủ nghĩa Mác – Lênin về bảo vệ Tổ quốc XHCN?", "a": "Đảng Cộng sản lãnh đạo mọi mặt sự nghiệp bảo vệ Tổ quốc XHCN.", "flag": false}, {"id": 27, "lesson": "Bài 2", "number": "3", "q": "Chủ tịch Hồ Chí Minh đã chỉ rõ cuộc chiến tranh của dân ta chống thực dân Pháp xâm lược là nhằm mục đích gì?", "a": "Bảo vệ độc lập, chủ quyền và thống nhất đất nước.", "flag": false}, {"id": 28, "lesson": "Bài 2", "number": "4", "q": "Vì sao Chủ tịch Hồ Chí Minh khẳng định phải dùng bạo lực cách mạng để giành lấy chính quyền và bảo vệ chính quyền?", "a": "Phải dùng bạo lực cách mạng chống lại bạo lực phản cách mạng.", "flag": false}, {"id": 29, "lesson": "Bài 2", "number": "5", "q": "Chủ tịch Hồ Chí Minh khẳng định sự ra đời của quân đội ta là thế nào?", "a": "Là một tất yếu có tính quy luật trong đấu tranh giai cấp, đấu tranh dân tộc ở Việt Nam.", "flag": false}, {"id": 30, "lesson": "Bài 2", "number": "6", "q": "Chủ tịch Hồ Chí Minh khẳng định hai nhiệm vụ chính của quân đội nhân dân Việt Nam là gì?", "a": "Chiến đấu bảo vệ Tổ quốc, tham gia lao động sản xuất góp phần xây dựng CNXH.", "flag": false}, {"id": 31, "lesson": "Bài 2", "number": "7", "q": "Theo quan điểm chủ nghĩa Mác-Lênin để bảo vệ tổ quốc XHCN ta cần phải làm gì?", "a": "Tăng cường tiềm lực quốc phòng gắn với phát triển kinh tế - xã hội.", "flag": false}, {"id": 32, "lesson": "Bài 2", "number": "8", "q": "Theo quan điểm chủ nghĩa Mác-Lênin bảo vệ tổ quốc XHCN là nghĩa vụ, trách nhiệm của ai?", "a": "Toàn dân.", "flag": false}, {"id": 33, "lesson": "Bài 2", "number": "9", "q": "Vai trò của Đảng Cộng sản Việt Nam trong sự nghiệp bảo vệ Tổ quốc XHCN Việt Nam là gì?", "a": "Đảng Cộng sản Việt Nam là người lãnh đạo sự nghiệp bảo vệ Tổ quốc Việt Nam.", "flag": false}, {"id": 34, "lesson": "Bài 2", "number": "10", "q": "Theo quan điểm chủ nghĩa Mác-Lênin bảo vệ tổ quốc XHCN là một tất yếu khách quan là vì?", "a": "Còn tồn tại đấu tranh giai cấp và âm mưu chống phá của thế lực thù địch; giữ vững độc lập, chủ quyền.", "flag": false}, {"id": 35, "lesson": "Bài 2", "number": "11", "q": "Theo quan điểm chủ nghĩa Mác-Lênin bảo vệ tổ quốc XHCN là một tất yếu khách quan là vì?", "a": "Xuất phát từ yêu cầu bảo vệ thành quả cách mạng và xây dựng CNXH.", "flag": false}, {"id": 36, "lesson": "Bài 2", "number": "12", "q": "Theo quan điểm chủ nghĩa Mác-Lênin bảo vệ tổ quốc XHCN là một tất yếu khách quan là vì?", "a": "Do bản chất cướp bóc của chủ nghĩa đế quốc và các thế lực phản động.", "flag": false}, {"id": 37, "lesson": "Bài 2", "number": "13", "q": "Theo tư tưởng Hồ Chí Minh, để thực hiện thắng lợi nhiệm vụ cách mạng trong giai đoạn mới, chúng ta cần:", "a": "Nâng cao tính thuyết phục công tác tư tưởng, tăng cường sự lãnh đạo của Đảng, phát huy thế hệ trẻ.", "flag": false}, {"id": 38, "lesson": "Bài 2", "number": "14", "q": "Theo tư tưởng Hồ Chí Minh, để thực hiện thắng lợi nhiệm vụ cách mạng trong giai đoạn mới, chúng ta cần:", "a": "Xây dựng tiềm lực toàn diện của đất nước, đặc biệt tiềm lực kinh tế, tạo ra thế và lực mới.", "flag": false}, {"id": 39, "lesson": "Bài 2", "number": "15", "q": "Quan điểm nào về chiến tranh theo quan điểm của chủ nghĩa Mác–Lênin là đúng đắn nhất?", "a": "Chiến tranh là một hiện tượng chính trị - xã hội có tính lịch sử.", "flag": false}, {"id": 40, "lesson": "Bài 2", "number": "16", "q": "Theo quan điểm chủ nghĩa Mác–Lênin nguồn gốc sâu xa dẫn đến sự xuất hiện, tồn tại của chiến tranh là gì?", "a": "Sự xuất hiện và tồn tại của chế độ chiếm hữu tư nhân về tư liệu sản xuất.", "flag": false}, {"id": 41, "lesson": "Bài 2", "number": "17", "q": "Theo quan điểm của chủ nghĩa Mác–Lênin, chính trị là sự phản ánh tập trung của:", "a": "Kinh tế.", "flag": false}, {"id": 42, "lesson": "Bài 2", "number": "18", "q": "Theo quan điểm của chủ nghĩa Mác-Lênin về quan hệ giữa chiến tranh với chính trị:", "a": "Chính trị quyết định chiến tranh; chiến tranh là công cụ của chính trị, là sự tiếp tục của chính trị bằng bạo lực.", "flag": false}, {"id": 43, "lesson": "Bài 2", "number": "19", "q": "Theo Chủ tịch Hồ Chí Minh cội nguồn của sức mạnh để giành thắng lợi trong chiến tranh ở nước ta là gì?", "a": "Sức mạnh toàn dân (lấy dân làm gốc, sức mạnh đại đoàn kết toàn dân tộc).", "flag": false}, {"id": 44, "lesson": "Bài 2", "number": "20", "q": "Chủ tịch Hồ Chí Minh khẳng định mục đích cuộc chiến tranh của nhân dân ta chống thực dân Pháp là?", "a": "Bảo vệ độc lập, chủ quyền và thống nhất đất nước.", "flag": false}, {"id": 45, "lesson": "Bài 2", "number": "21", "q": "Tư tưởng Hồ Chí Minh xác định thái độ đối với chiến tranh là?", "a": "Yêu chuộng hòa bình, ủng hộ chiến tranh chính nghĩa, phản đối chiến tranh phi nghĩa.", "flag": false}, {"id": 46, "lesson": "Bài 2", "number": "22", "q": "Trong tác phẩm Bản án chế độ Thực dân Pháp, Chủ tịch Hồ Chí Minh đã sử dụng hình ảnh gì để khái quát bản chất bóc lột của chủ nghĩa tư bản?", "a": "Con đỉa hai vòi.", "flag": false}, {"id": 47, "lesson": "Bài 2", "number": "23", "q": "Theo tư tưởng Hồ Chí Minh, đánh giặc phải bằng sức mạnh của toàn dân, trong đó phải có lực lượng nào làm nòng cốt?", "a": "Lực lượng vũ trang nhân dân.", "flag": false}, {"id": 48, "lesson": "Bài 2", "number": "24", "q": "Quan điểm về nguồn gốc của quân đội nào là đúng đắn nhất?", "a": "Quân đội ra đời khi xã hội xuất hiện chế độ tư hữu tư liệu sản xuất và phân hóa giai cấp đối kháng.", "flag": false}, {"id": 49, "lesson": "Bài 2", "number": "25", "q": "Quân đội là công cụ bạo lực vũ trang của lực lượng nào?", "a": "Giai cấp thống trị / Nhà nước.", "flag": true}, {"id": 50, "lesson": "Bài 2", "number": "26", "q": "Bản chất giai cấp quyết định nội dung nào của quân đội?", "a": "Mục tiêu chiến đấu.", "flag": false}, {"id": 51, "lesson": "Bài 2", "number": "27", "q": "Theo tư tưởng Hồ Chí Minh nội dung nào là cơ sở, nền tảng để xây dựng quân đội vững mạnh toàn diện?", "a": "Giáo dục (chính trị, tư tưởng).", "flag": false}, {"id": 52, "lesson": "Bài 2", "number": "28", "q": "Theo tư tưởng Hồ Chí Minh nhân tố quyết định sự hình thành và phát triển bản chất giai cấp công nhân của quân đội ta là?", "a": "Sự lãnh đạo của Đảng Cộng sản Việt Nam.", "flag": false}, {"id": 53, "lesson": "Bài 2", "number": "29", "q": "“Mạnh được yếu thua” là thể hiện vấn đề gì trong tư tưởng Hồ Chí Minh về chiến tranh?", "a": "Quy luật chiến tranh.", "flag": false}, {"id": 54, "lesson": "Bài 2", "number": "30", "q": "Nội dung nào được xác định là tư tưởng chủ đạo trong toàn bộ di sản lý luận Hồ Chí Minh?", "a": "Độc lập dân tộc gắn liền với chủ nghĩa xã hội.", "flag": false}, {"id": 55, "lesson": "Bài 2", "number": "31", "q": "Theo quan điểm Chủ nghĩa Mác–Lênin, bản chất giai cấp của quân đội thể hiện trên những mặt cơ bản nào?", "a": "Chính trị, tư tưởng, tổ chức.", "flag": false}, {"id": 56, "lesson": "Bài 2", "number": "32", "q": "Theo quan điểm của Lênin, bảo vệ Tổ quốc xã hội chủ nghĩa là nghĩa vụ, trách nhiệm của ai?", "a": "Toàn dân.", "flag": false}, {"id": 57, "lesson": "Bài 2", "number": "33", "q": "Theo quan điểm Lênin, trong những điều kiện xác định, yếu tố nào giữ vai trò quyết định đến sức mạnh chiến đấu của quân đội?", "a": "Chính trị - tinh thần.", "flag": false}, {"id": 58, "lesson": "Bài 2", "number": "34", "q": "Theo tư tưởng Hồ Chí Minh, Quân đội nhân dân Việt Nam mang bản chất của giai cấp nào?", "a": "Giai cấp công nhân.", "flag": false}, {"id": 59, "lesson": "Bài 2", "number": "35", "q": "Tư duy mới của Đảng ta về bảo vệ Tổ quốc thể hiện ở nội dung nào sau đây?", "a": "Chủ động ngăn ngừa nguy cơ chiến tranh từ sớm, từ xa, từ khi nước chưa nguy.", "flag": false}, {"id": 60, "lesson": "Bài 2", "number": "36", "q": "Đối sách mềm dẻo, linh hoạt, sáng tạo của Đảng ta về bảo vệ Tổ quốc trong tình hình mới thể hiện nội dung nào?", "a": "Kiên quyết, kiên trì (thực hiện phương châm Dĩ bất biến, ứng vạn biến).", "flag": false}, {"id": 61, "lesson": "Bài 2", "number": "37", "q": "Theo tư tưởng Hồ Chí Minh, Quân đội nhân dân Việt Nam có những chức năng?", "a": "3 chức năng: Đội quân chiến đấu, đội quân công tác, đội quân lao động sản xuất.", "flag": false}, {"id": 62, "lesson": "Bài 2", "number": "38", "q": "Sức mạnh bảo vệ Tổ quốc XHCN theo tư tưởng Hồ Chí Minh?", "a": "Sức mạnh tổng hợp của đại đoàn kết toàn dân tộc kết hợp sức mạnh thời đại.", "flag": false}, {"id": 63, "lesson": "Bài 2", "number": "39", "q": "Chủ tịch Hồ Chí Minh xác định nghĩa vụ, trách nhiệm của công dân về bảo vệ Tổ quốc?", "a": "Bảo vệ Tổ quốc là nghĩa vụ thiêng liêng và quyền cao quý của mọi công dân.", "flag": false}, {"id": 64, "lesson": "Bài 2", "number": "40", "q": "Khẳng định phương án nào sau đây SAI?", "a": "Chọn phương án phủ nhận sự lãnh đạo của Đảng đối với Quân đội hoặc coi cuộc chiến tranh BVTQ là phi nghĩa.", "flag": false}, {"id": 65, "lesson": "Bài 2", "number": "41", "q": "Trường hợp nào sau đây chỉ luận điểm phản động?", "a": "Luận điểm đòi phi chính trị hóa quân đội, đòi tách Quân đội khỏi sự lãnh đạo của Đảng.", "flag": false}, {"id": 66, "lesson": "Bài 2", "number": "42", "q": "Mục đích của luận điệu phi chính trị hóa quân đội là gì?", "a": "Tước bỏ sự lãnh đạo của Đảng đối với quân đội, làm biến chất và suy yếu Quân đội từ bên trong.", "flag": false}, {"id": 67, "lesson": "Bài 2", "number": "43", "q": "Theo tư tưởng Hồ Chí Minh sử dụng bạo lực cách mạng là để?", "a": "Chống lại bạo lực phản cách mạng, giành và giữ chính quyền, bảo vệ độc lập tự do.", "flag": false}, {"id": 68, "lesson": "Bài 2", "number": "44", "q": "Theo quan điểm chủ nghĩa Mác-Lê nin Quân đội ra đời khi?", "a": "Khi xã hội xuất hiện chế độ tư hữu tư liệu sản xuất và phân hóa giai cấp đối kháng, nhà nước ra đời.", "flag": false}, {"id": 69, "lesson": "Bài 2", "number": "45", "q": "Khẳng định nào sau đây ĐÚNG?", "a": "Khẳng định tính chất chính nghĩa, tự vệ cách mạng, toàn dân của cuộc chiến tranh bảo vệ Tổ quốc.", "flag": false}, {"id": 70, "lesson": "Bài 3", "number": "1", "q": "Tiềm lực quốc phòng, an ninh là gì?", "a": "Khả năng về nhân lực, vật lực, tài chính có thể huy động để thực hiện nhiệm vụ quốc phòng, an ninh.", "flag": false}, {"id": 71, "lesson": "Bài 3", "number": "2", "q": "Xây dựng nền quốc phòng toàn dân – an ninh nhân dân gồm những nội dung nào?", "a": "Xây dựng tiềm lực và xây dựng thế trận quốc phòng, an ninh.", "flag": false}, {"id": 72, "lesson": "Bài 3", "number": "3", "q": "Trong củng cố xây dựng nền quốc phòng, an ninh nhân dân, lực lượng nào là nòng cốt?", "a": "Lực lượng Quân đội nhân dân và Công an nhân dân.", "flag": false}, {"id": 73, "lesson": "Bài 3", "number": "4", "q": "Nội dung xây dựng tiềm lực kinh tế của nền quốc phòng toàn dân là gì?", "a": "Đẩy mạnh Công nghiệp hóa, Hiện đại hóa đất nước, xây dựng nền kinh tế độc lập tự chủ.", "flag": false}, {"id": 74, "lesson": "Bài 3", "number": "5", "q": "Xây dựng tiềm lực kinh tế của nền quốc phòng toàn dân, an ninh nhân dân cần đặc biệt quan tâm nội dung nào?", "a": "Đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước.", "flag": false}, {"id": 75, "lesson": "Bài 3", "number": "6", "q": "Tiềm lực kinh tế của nền quốc phòng toàn dân, an ninh nhân dân là gì?", "a": "Khả năng huy động nguồn lực kinh tế của đất nước để phục vụ cho nhiệm vụ quốc phòng, an ninh.", "flag": false}, {"id": 76, "lesson": "Bài 3", "number": "7", "q": "Xây dựng tiềm lực khoa học công nghệ của nền quốc phòng toàn dân, an ninh nhân dân là tạo nên khả năng gì?", "a": "Tạo nên khả năng về khoa học, công nghệ của quốc gia có thể khai thác, phục vụ quốc phòng, an ninh.", "flag": false}, {"id": 77, "lesson": "Bài 3", "number": "8", "q": "Tiềm lực chính trị, tinh thần của nền QPTD, ANND là gì?", "a": "Khả năng về chính trị, tinh thần có thể huy động nhằm tạo thành sức mạnh thực hiện nhiệm vụ QP-AN.", "flag": false}, {"id": 78, "lesson": "Bài 3", "number": "9", "q": "Một trong các nội dung xây dựng thực lực nền quốc phòng toàn dân, an ninh nhân dân là gì?", "a": "Xây dựng tiềm lực quốc phòng, bao gồm tiềm lực chính trị tinh thần, kinh tế, khoa học công nghệ và quân sự.", "flag": false}, {"id": 79, "lesson": "Bài 3", "number": "10", "q": "Một trong những nội dung xây dựng tiềm lực quân sự, an ninh là gì?", "a": "Gắn công nghiệp hóa, hiện đại hóa đất nước với tăng cường vũ khí trang bị cho lực lượng vũ trang.", "flag": false}, {"id": 80, "lesson": "Bài 3", "number": "11", "q": "Một trong những nội dung xây dựng thế trận quốc phòng, an ninh nhân dân là gì?", "a": "Tổ chức phòng thủ dân sự, kết hợp cải tạo địa hình với xây dựng hạ tầng và các công trình quốc phòng an ninh.", "flag": false}, {"id": 81, "lesson": "Bài 3", "number": "12", "q": "Một trong các biện pháp xây dựng nền quốc phòng toàn dân, an ninh nhân dân là?", "a": "Thường xuyên thực hiện giáo dục quốc phòng và an ninh.", "flag": false}, {"id": 82, "lesson": "Bài 3", "number": "13", "q": "Theo Khoản 1 Điều 2 Luật Quốc phòng năm 2019 thì quốc phòng là gì?", "a": "Công cuộc giữ nước bằng sức mạnh tổng hợp của toàn dân tộc, trong đó sức mạnh quân sự là đặc trưng, LLVTND làm nòng cốt.", "flag": false}, {"id": 83, "lesson": "Bài 3", "number": "14", "q": "Đảng ta khẳng định vị trí của nền quốc phòng toàn dân, an ninh nhân dân:", "a": "Luôn luôn coi trọng quốc phòng – an ninh, coi đó là nhiệm vụ chiến lược gắn bó chặt chẽ.", "flag": false}, {"id": 84, "lesson": "Bài 3", "number": "15", "q": "Nền quốc phòng toàn dân là sức mạnh quốc phòng của đất nước, được xây dựng trên nền tảng nào?", "a": "Chính trị, kinh tế, tinh thần, khoa học - công nghệ, quốc phòng - an ninh...", "flag": false}, {"id": 85, "lesson": "Bài 3", "number": "16", "q": "Nền quốc phòng toàn dân ở ta hiện nay mang tính chất?", "a": "Toàn dân, toàn diện, độc lập, tự do, tự lực, tự chủ, tự cường.", "flag": false}, {"id": 86, "lesson": "Bài 3", "number": "17", "q": "Đặc trưng nào thể hiện sự khác nhau về bản chất trong xây dựng nền quốc phòng, an ninh của nước ta với các nước khác?", "a": "Chỉ có mục đích duy nhất là tự vệ chính đáng.", "flag": false}, {"id": 87, "lesson": "Bài 3", "number": "18", "q": "Đặc trưng nào mang tính truyền thống của nền quốc phòng toàn dân, an ninh nhân dân?", "a": "Nền quốc phòng, an ninh vì dân, của dân và toàn thể nhân dân tiến hành.", "flag": false}, {"id": 88, "lesson": "Bài 3", "number": "19", "q": "Mục đích xây dựng nền quốc phòng toàn dân, an ninh nhân dân là:", "a": "Tạo sức mạnh tổng hợp, tạo thế chủ động bảo vệ vững chắc Tổ quốc.", "flag": false}, {"id": 89, "lesson": "Bài 3", "number": "20", "q": "Tiềm lực quốc phòng ở nước ta hiện nay được hiểu như thế nào?", "a": "Khả năng về nhân lực, vật lực, tài chính, tổng hợp các yếu tố trong và ngoài nước có thể huy động.", "flag": false}, {"id": 90, "lesson": "Bài 3", "number": "21", "q": "Theo luật quốc phòng ở ta hiện nay thì mục đích xây dựng thế trận quốc phòng toàn dân để làm gì?", "a": "Tổ chức, triển khai, bố trí lực lượng và tiềm lực quốc phòng trên toàn bộ lãnh thổ, bảo đảm đối phó thắng lợi mọi âm mưu.", "flag": false}, {"id": 91, "lesson": "Bài 3", "number": "22", "q": "Theo luật quốc phòng ở ta hiện nay thì đâu là nguyên tắc hoạt động quốc phòng?", "a": "Xây dựng nền quốc phòng toàn dân và thế trận quốc phòng toàn dân, gắn liền với nền an ninh nhân dân và thế trận an ninh nhân dân.", "flag": false}, {"id": 92, "lesson": "Bài 3", "number": "23", "q": "Đảng ta xác định tầm quan trọng của nhiệm vụ củng cố, tăng cường quốc phòng hiện nay như thế nào?", "a": "Nhiệm vụ trọng yếu và thường xuyên.", "flag": false}, {"id": 93, "lesson": "Bài 3", "number": "24", "q": "Hai nhiệm vụ chiến lược của cách mạng Việt Nam hiện nay là:", "a": "Xây dựng chủ nghĩa xã hội và bảo vệ Tổ quốc xã hội chủ nghĩa.", "flag": false}, {"id": 94, "lesson": "Bài 3", "number": "25", "q": "Một trong những nội dung trong chính sách của Nhà nước ta về quốc phòng là?", "a": "Hòa bình, tự vệ; kiên quyết giải quyết tranh chấp bằng biện pháp hòa bình; thực hiện chính sách 4 Không.", "flag": false}, {"id": 95, "lesson": "Bài 3", "number": "26", "q": "Chính sách của Nhà nước về quốc phòng là?", "a": "Hòa bình tự vệ.", "flag": false}, {"id": 96, "lesson": "Bài 3", "number": "27", "q": "Quan điểm chính sách của Đảng và Nhà nước ta về thực hiện đối ngoại quốc phòng là?", "a": "Độc lập, tự chủ, tự cường; tạo môi trường quốc tế thuận lợi, ngăn ngừa chiến tranh dưới mọi hình thức.", "flag": false}, {"id": 97, "lesson": "Bài 3", "number": "28", "q": "Quan điểm chính sách của Đảng và Nhà nước ta về thực hiện đối ngoại quốc phòng là?", "a": "Độc lập, tự chủ, đa phương hóa, đa dạng hóa; giữ nước từ sớm, từ xa.", "flag": false}, {"id": 98, "lesson": "Bài 3", "number": "29", "q": "Đảng ta khẳng định vị trí của nền quốc phòng toàn dân, an ninh nhân dân?", "a": "Nhiệm vụ trọng yếu, thường xuyên, gắn kết chặt chẽ với phát triển kinh tế - xã hội.", "flag": false}, {"id": 99, "lesson": "Bài 3", "number": "30", "q": "Một trong những nội dung xây dựng thế trận quốc phòng toàn dân, an ninh nhân dân là?", "a": "Xây dựng khu vực phòng thủ tỉnh (thành phố), phân vùng chiến lược, gắn kết thế trận QPTD với ANND.", "flag": false}, {"id": 100, "lesson": "Bài 3", "number": "31", "q": "Trong nội dung xây dựng tiềm lực QP - AN thì tiềm lực kinh tế có vị trí?", "a": "Là cơ sở vật chất, kỹ thuật cho các tiềm lực khác, tạo sức mạnh tổng hợp cho quốc phòng, an ninh.", "flag": false}, {"id": 101, "lesson": "Bài 3", "number": "32", "q": "Chọn phương án đúng điền vào chỗ ...: Trong khi đặt trọng tâm vào nhiệm vụ xây dựng CNXH... coi đó là ... gắn bó chặt chẽ.", "a": "hai nhiệm vụ chiến lược.", "flag": false}, {"id": 102, "lesson": "Bài 4", "number": "1", "q": "Một trong những âm mưu, thủ đoạn của kẻ thù khi xâm lược nước ta là:", "a": "Thực hiện chiến lược đánh nhanh, thắng nhanh, kết hợp tấn công quân sự bên ngoài với gây bạo loạn lật đổ bên trong.", "flag": false}, {"id": 103, "lesson": "Bài 4", "number": "2", "q": "Tiến hành chiến tranh xâm lược nước ta, khó khăn cơ bản nhất của địch là:", "a": "Phải đối đầu với một dân tộc có truyền thống kiên cường chống ngoại xâm, tác chiến trong điều kiện địa hình phức tạp.", "flag": false}, {"id": 104, "lesson": "Bài 4", "number": "3", "q": "Một trong những đặc điểm của chiến tranh nhân dân bảo vệ Tổ quốc là:", "a": "Tính toàn dân, toàn diện.", "flag": false}, {"id": 105, "lesson": "Bài 4", "number": "4", "q": "Điểm mạnh cơ bản của địch khi tiến hành chiến tranh xâm lược nước ta là:", "a": "Tiềm lực kinh tế, quân sự, khoa học công nghệ rất lớn, vũ khí trang bị hiện đại.", "flag": false}, {"id": 106, "lesson": "Bài 4", "number": "5", "q": "Chiến tranh nhân dân bảo vệ Tổ quốc là cuộc chiến tranh chính nghĩa, tự vệ cách mạng... là một nội dung của:", "a": "Quan điểm của Đảng Cộng sản Việt Nam về chiến tranh nhân dân bảo vệ Tổ quốc XHCN.", "flag": false}, {"id": 107, "lesson": "Bài 4", "number": "6", "q": "Một trong những nội dung chủ yếu của chiến tranh nhân dân là:", "a": "Tổ chức thế trận chiến tranh nhân dân; tổ chức lực lượng chiến tranh nhân dân; phối hợp chống địch công bên ngoài và bạo loạn bên trong.", "flag": false}, {"id": 108, "lesson": "Bài 4", "number": "7", "q": "Một trong những quan điểm của Đảng ta về chiến tranh nhân dân bảo vệ tổ quốc là:", "a": "Tiến hành chiến tranh nhân dân, toàn dân đánh giặc lấy lực lượng vũ trang nhân dân làm nòng cốt.", "flag": false}, {"id": 109, "lesson": "Bài 4", "number": "8", "q": "Chiến tranh nhân dân bảo vệ tổ quốc là cuộc chiến tranh mang tính chất:", "a": "Chính nghĩa, tự vệ cách mạng, toàn dân, toàn diện, sâu sắc và hiện đại.", "flag": false}, {"id": 110, "lesson": "Bài 4", "number": "9", "q": "Một trong những đặc điểm của chiến tranh nhân dân bảo vệ Tổ quốc là:", "a": "Tính toàn dân, toàn diện.", "flag": false}, {"id": 111, "lesson": "Bài 4", "number": "10", "q": "Kết hợp sức mạnh dân tộc với sức mạnh thời đại, phát huy tinh thần tự lực tự cường... là một trong những nội dung của:", "a": "Quan điểm chiến tranh nhân dân bảo vệ Tổ quốc Việt Nam xã hội chủ nghĩa.", "flag": false}, {"id": 112, "lesson": "Bài 4", "number": "11", "q": "Một trong những quan điểm của Đảng trong chiến tranh nhân dân bảo vệ tổ quốc là:", "a": "Tiến hành chiến tranh nhân dân, toàn dân đánh giặc lấy lực lượng vũ trang nhân dân làm nòng cốt.", "flag": false}, {"id": 113, "lesson": "Bài 4", "number": "12", "q": "Tính hiện đại trong chiến tranh nhân dân bảo vệ tổ quốc ở Việt Nam là:", "a": "Sử dụng vũ khí trang bị hiện đại, kết hợp nghệ thuật quân sự truyền thống với tri thức khoa học công nghệ mới.", "flag": false}, {"id": 114, "lesson": "Bài 4", "number": "13", "q": "Quan điểm thực hiện toàn dân đánh giặc trong chiến tranh nhân dân bảo vệ tổ quốc có ý nghĩa:", "a": "Bào chế sức mạnh tổng hợp của toàn dân tộc, làm cho kẻ thù sa vào biển lửa của chiến tranh nhân dân.", "flag": false}, {"id": 115, "lesson": "Bài 4", "number": "14", "q": "Trong chiến tranh nhân dân bảo vệ Tổ quốc, phải kết hợp kháng chiến với xây dựng, vừa chiến đấu vừa sản xuất, vì:", "a": "Nhằm duy trì sức người, sức của cho chiến tranh lâu dài, giữ vững đời sống nhân dân.", "flag": false}, {"id": 116, "lesson": "Bài 4", "number": "15", "q": "Trong chiến tranh nhân dân bảo vệ Tổ quốc, phải kết hợp đấu tranh quân sự với bảo đảm an ninh chính trị, giữ gìn TTATXH... vì:", "a": "Đập tan âm mưu trong đánh ra, ngoài đánh vào của địch, giữ vững hậu phương ổn định.", "flag": false}, {"id": 117, "lesson": "Bài 4", "number": "16", "q": "Kết hợp sức mạnh dân tộc với sức mạnh thời đại nhằm:", "a": "Tạo nên sức mạnh tổng hợp bao gồm cả nội lực và ngoại lực.", "flag": false}, {"id": 118, "lesson": "Bài 4", "number": "17", "q": "Thế trận chiến tranh nhân dân là:", "a": "Cách tổ chức, bố trí lực lượng, tiềm lực quốc phòng trên toàn bộ lãnh thổ theo kế hoạch thống nhất để đánh địch.", "flag": false}, {"id": 119, "lesson": "Bài 4", "number": "18", "q": "Trong chiến tranh nhân dân bảo vệ tổ quốc, thế trận của chiến tranh được triển khai:", "a": "Theo cách toàn diện, lấy lực lượng vũ trang làm nòng cốt, kết hợp quân với dân và các lực lượng khác trên mọi vùng địa bàn.", "flag": false}, {"id": 120, "lesson": "Bài 4", "number": "19", "q": "Lực lượng trong chiến tranh nhân dân bảo vệ Tổ quốc gồm:", "a": "Lực lượng toàn dân (lực lượng chính trị) và Lực lượng vũ trang nhân dân làm nòng cốt.", "flag": false}, {"id": 121, "lesson": "Bài 4", "number": "20", "q": "Trong chiến tranh nhân dân bảo vệ Tổ quốc, chúng ta phải chuẩn bị mọi mặt cả nước cũng như từng khu vực để đủ sức đánh được lâu dài, vì:", "a": "Kẻ thù xâm lược có tiềm lực quân sự, kinh tế mạnh hơn ta nhiều lần.", "flag": false}, {"id": 122, "lesson": "Bài 4", "number": "21", "q": "Trong tổ chức lực lượng chiến tranh nhân dân bảo vệ Tổ quốc, lực lượng vũ trang phải được xây dựng:", "a": "Hùng mạnh toàn diện, tinh gọn, lấy xây dựng về chính trị làm cơ sở.", "flag": false}, {"id": 123, "lesson": "Bài 4", "number": "22", "q": "Hình thái đất nước được chuẩn bị sẵn sàng, thế trận quốc phòng, an ninh nhân dân ngày càng được củng cố vững chắc... là:", "a": "Đặc điểm / thuận lợi của chiến tranh nhân dân bảo vệ Tổ quốc.", "flag": true}, {"id": 124, "lesson": "Bài 4", "number": "23", "q": "Mục tiêu trước mắt của chiến tranh nhân dân bảo vệ Tổ quốc ở nước ta hiện nay là:", "a": "Đánh bại ý đồ xâm lược của địch, bảo vệ vững chắc độc lập, chủ quyền, toàn vẹn lãnh thổ.", "flag": false}, {"id": 125, "lesson": "Bài 4", "number": "24", "q": "Quan điểm thực hiện toàn dân đánh giặc trong chiến tranh nhân dân bảo vệ Tổ quốc khẳng định:", "a": "Quần chúng nhân dân là người quyết định thắng lợi của chiến tranh, lực lượng vũ trang làm nòng cốt.", "flag": false}, {"id": 126, "lesson": "Bài 4", "number": "25", "q": "Yếu tố quyết định thắng lợi của chiến tranh nhân dân bảo vệ Tổ quốc?", "a": "Sự lãnh đạo đúng đắn của Đảng Cộng sản Việt Nam và sức mạnh khối đại đoàn kết toàn dân tộc.", "flag": false}, {"id": 127, "lesson": "Bài 4", "number": "26", "q": "Quan điểm nào được xác định là cơ bản xuyên suốt, thể hiện tính nhân dân sâu sắc trong Chiến tranh Nhân dân BVTQ?", "a": "Quan điểm tiến hành chiến tranh nhân dân, toàn dân đánh giặc.", "flag": false}, {"id": 128, "lesson": "Bài 4", "number": "27", "q": "Tính độc đáo trong tác chiến của ta so với tác chiến của quân đội các nước khác ở chỗ nào?", "a": "Đánh bằng sức mạnh tổng hợp, đánh bằng mưu kế, lấy nhỏ đánh lớn, lấy ít địch nhiều.", "flag": false}, {"id": 129, "lesson": "Bài 4", "number": "28", "q": "Yếu tố nào giữ vai trò quyết định để giành thắng lợi trong chiến tranh nhân dân ở nước ta?", "a": "Con người và nhân tố chính trị - tinh thần.", "flag": false}, {"id": 130, "lesson": "Bài 4", "number": "29", "q": "Yếu tố nào là yếu tố chủ yếu để giành thắng lợi trong chiến tranh nhân dân ở ta?", "a": "Sức mạnh đại đoàn kết toàn dân tộc dưới sự lãnh đạo của Đảng.", "flag": false}, {"id": 131, "lesson": "Bài 4", "number": "30", "q": "Trong chiến tranh nhân dân ở ta lực lượng nào xác định là lực lượng nòng cốt?", "a": "Lực lượng vũ trang nhân dân (Bộ đội chủ lực, Bộ đội địa phương, Dân quân tự vệ).", "flag": false}, {"id": 132, "lesson": "Bài 4", "number": "31", "q": "Đối tượng của chiến tranh nhân dân bảo vệ Tổ quốc?", "a": "Chủ nghĩa đế quốc và các thế lực thù địch tiến hành chiến tranh xâm lược hoặc bạo loạn lật đổ.", "flag": false}, {"id": 133, "lesson": "Bài 4", "number": "32", "q": "Quan điểm thực hiện toàn dân đánh giặc trong chiến tranh nhân dân bảo vệ Tổ quốc có ý nghĩa?", "a": "Huy động tối đa sức người, sức của, tạo thế trận bủa vây kẻ thù.", "flag": false}, {"id": 134, "lesson": "Bài 4", "number": "33", "q": "Trong 4 mặt trận sau, mặt trận nào có ý nghĩa quyết định trong chiến tranh?", "a": "Mặt trận quân sự.", "flag": false}, {"id": 135, "lesson": "Bài 4", "number": "34", "q": "Lực lượng trong chiến tranh nhân dân bảo vệ Tổ quốc gồm?", "a": "Lực lượng toàn dân và Lực lượng vũ trang nhân dân làm nòng cốt.", "flag": false}, {"id": 136, "lesson": "Bài 4", "number": "35", "q": "Tiến hành chiến tranh toàn diện nhưng phải lấy mặt trận nào là chủ yếu, quyết định?", "a": "Mặt trận quân sự.", "flag": false}, {"id": 137, "lesson": "Bài 4", "number": "36", "q": "Trong chiến tranh nhân dân phải ra sức thu hẹp không gian, rút ngắn thời gian nhằm mục đích gí?", "a": "Làm thất bại chiến lược đánh nhanh, thắng nhanh của địch.", "flag": false}, {"id": 138, "lesson": "Bài 4", "number": "37", "q": "Trong chiến tranh ta càng đánh càng mạnh vì sao?", "a": "Vì chiến tranh của ta là chính nghĩa, dựa vào sức mạnh toàn dân, càng đánh càng tích lũy kinh nghiệm.", "flag": false}, {"id": 139, "lesson": "Bài 4", "number": "38", "q": "Quan điểm kết hợp đấu tranh quân sự với bảo đảm an ninh chính trị, giữ gìn TTATXH … có nghĩa là?", "a": "Vừa kháng chiến chống địch bên ngoài, vừa giữ vững an ninh nội bộ, dập tắt bạo loạn bên trong.", "flag": false}, {"id": 140, "lesson": "Bài 4", "number": "39", "q": "Tranh thủ sự giúp đỡ quốc tế, sự đồng tình ủng hộ của nhân dân tiến bộ... thể hiện tinh thần quan điểm nào?", "a": "Kết hợp sức mạnh dân tộc với sức mạnh thời đại.", "flag": false}, {"id": 141, "lesson": "Bài 4", "number": "40", "q": "Những câu trích dưới đây, câu nào không phản ánh tinh thần chiến tranh nhân dân?", "a": "Chọn câu thể hiện tư tưởng đơn thuần quân sự, coi nhẹ sức mạnh của quần chúng nhân dân.", "flag": false}, {"id": 142, "lesson": "Bài 4", "number": "41", "q": "Nhận định nào sau đây đúng?", "a": "Nhận định khẳng định tính chất chính nghĩa, toàn dân, toàn diện của chiến tranh nhân dân bảo vệ Tổ quốc.", "flag": false}, {"id": 143, "lesson": "Bài 5", "number": "1", "q": "Lực lượng vũ trang nhân dân Việt Nam gồm:", "a": "Quân đội, Công an, Dân quân tự vệ.", "flag": false}, {"id": 144, "lesson": "Bài 5", "number": "2", "q": "Quân đội nhân dân Việt Nam thành lập ngày, tháng, năm nào?", "a": "22/12/1944.", "flag": false}, {"id": 145, "lesson": "Bài 5", "number": "3", "q": "Một trong những đặc điểm thuận lợi trong xây dựng lực lượng vũ trang nhân dân là:", "a": "Truyền thống yêu nước, đoàn kết của nhân dân cùng sự lãnh đạo tuyệt đối, trực tiếp về mọi mặt của Đảng.", "flag": false}, {"id": 146, "lesson": "Bài 5", "number": "4", "q": "Lực lượng vũ trang nhân dân trong bảo vệ Tổ quốc có vị trí là lực lượng:", "a": "Lực lượng nòng cốt.", "flag": false}, {"id": 147, "lesson": "Bài 5", "number": "5", "q": "Dân quân tự vệ Việt Nam thành lập ngày, tháng năm nào?", "a": "28/03/1935.", "flag": false}, {"id": 148, "lesson": "Bài 5", "number": "6", "q": "Một trong những biện pháp chủ yếu trong xây dựng lực lượng vũ trang là:", "a": "Giữ vững sự lãnh đạo của Đảng; nâng cao chất lượng huấn luyện; chấn chỉnh biên chế; từng bước hiện đại hóa.", "flag": false}, {"id": 149, "lesson": "Bài 5", "number": "7", "q": "Công an nhân dân Việt Nam thành lập ngày, tháng, năm nào?", "a": "19/08/1945.", "flag": false}, {"id": 150, "lesson": "Bài 5", "number": "8", "q": "Thách thức lớn đối với chúng ta trong xây dựng lực lượng vũ trang nhân dân là:", "a": "Chiến lược Diễn biến hòa bình, bạo loạn lật đổ, âm mưu phi chính trị hóa lực lượng vũ trang.", "flag": false}, {"id": 151, "lesson": "Bài 5", "number": "9", "q": "Đối với sự tác động của bên ngoài thì khó khăn lớn cho ta trong xây dựng lực lượng vũ trang nhân dân là:", "a": "Thế giới biến động nhanh chóng, phức tạp; cạnh tranh chiến lược giữa các nước lớn.", "flag": false}, {"id": 152, "lesson": "Bài 5", "number": "10", "q": "Để đảm bảo sự lãnh đạo của Đảng đối với lực lượng vũ trang nhân dân, phải xây dựng các tổ chức Đảng:", "a": "Vững mạnh chính trị, tư tưởng, tổ chức, đạo đức; giữ vững cơ chế lãnh đạo tuyệt đối, trực tiếp.", "flag": false}, {"id": 153, "lesson": "Bài 5", "number": "11", "q": "Bảo đảm lực lượng vũ trang nhân dân luôn trong tư thế sẵn sàng chiến đấu và chiến đấu thắng lợi... phản ánh:", "a": "Chức năng, nhiệm vụ chủ yếu, cơ bản, thường xuyên của lực lượng vũ trang.", "flag": false}, {"id": 154, "lesson": "Bài 5", "number": "12", "q": "Đảng Cộng sản Việt Nam lãnh đạo tuyệt đối lực lượng vũ trang nhân dân Việt Nam được thể hiện:", "a": "Độc tôn lãnh đạo, không nhường hoặc chia sẻ quyền lãnh đạo cho bất kỳ giai cấp, lực lượng nào.", "flag": false}, {"id": 155, "lesson": "Bài 5", "number": "13", "q": "Mâu thuẫn chủ yếu hiện nay và những năm tới trong xây dựng lực lượng vũ trang là:", "a": "Nhu cầu đầu tư cho quốc phòng - an ninh ngày càng lớn vs Khả năng kinh tế và ngân sách Nhà nước còn hạn hẹp.", "flag": false}, {"id": 156, "lesson": "Bài 5", "number": "14", "q": "Trận đánh đầu tiên của Quân đội nhân dân Việt Nam sau khi được thành lập là:", "a": "Trận Phai Khắt và Nà Ngần vào ngày 25 và 26/12/1944.", "flag": false}, {"id": 157, "lesson": "Bài 5", "number": "15", "q": "Trong những biện pháp chủ yếu xây dựng LLVT, việc chấn chỉnh tổ chức biên chế đối với các đơn vị bộ đội chủ lực là:", "a": "Điều chỉnh theo hướng gọn, mạnh, cơ động, có sức chiến đấu cao.", "flag": false}, {"id": 158, "lesson": "Bài 5", "number": "16", "q": "Luật Dân quân tự vệ được ban hành năm:", "a": "Năm 2019 (ban hành ngày 22/11/2019).", "flag": false}, {"id": 159, "lesson": "Bài 5", "number": "17", "q": "Kế sách Ngụ binh ư nông của ông cha ta được vận dụng hiện nay trong xây dựng lực lượng nào?", "a": "Lực lượng dự bị động viên.", "flag": false}, {"id": 160, "lesson": "Bài 5", "number": "18", "q": "Quá trình hiện đại hóa quân đội phải gắn với quá trình nào?", "a": "Công nghiệp hóa, hiện đại hóa đất nước và phát triển công nghiệp quốc phòng.", "flag": false}, {"id": 161, "lesson": "Bài 5", "number": "19", "q": "Lực lượng thường trực của Quân đội nhân dân Việt Nam bao gồm các lực lượng nào?", "a": "Bộ đội chủ lực và Bộ đội địa phương.", "flag": false}, {"id": 162, "lesson": "Bài 5", "number": "20", "q": "Lãnh đạo và quản lý lực lượng vũ trang nhân dân Việt Nam là tổ chức nào?", "a": "Đảng Cộng sản Việt Nam lãnh đạo tuyệt đối, trực tiếp; Nhà nước CHXHCNVN thống nhất quản lý.", "flag": false}, {"id": 163, "lesson": "Bài 5", "number": "21", "q": "Xây dựng lực lượng hùng hậu, được huấn luyện và quản lí tốt, bảo đảm khi cần thiết có thể động viên nhanh...", "a": "Lực lượng dự bị động viên.", "flag": false}, {"id": 164, "lesson": "Bài 5", "number": "22", "q": "Luật Quốc phòng xác định nguyên tắc hoạt động của LLVTND trên cơ sở", "a": "Tuân thủ Hiến pháp, pháp luật; đặt dưới sự lãnh đạo của Đảng, sự quản lý của Nhà nước.", "flag": false}, {"id": 165, "lesson": "Bài 5", "number": "23", "q": "Luật Quốc phòng xác định nhiệm vụ cơ bản quyết định của lực lượng vũ trang nhân dân là gì?", "a": "Sẵn sàng chiến đấu và chiến đấu bảo vệ Tổ quốc.", "flag": false}, {"id": 166, "lesson": "Bài 5", "number": "24", "q": "Đại hội XIV dự báo khó khăn thách thức bao trùm đối với chúng ta trong xây dựng lực lượng vũ trang nhân dân là:", "a": "Thách thức an ninh truyền thống và phi truyền thống đan xen; sự chống phá của các thế lực thù địch.", "flag": false}, {"id": 167, "lesson": "Bài 5", "number": "25", "q": "Văn kiện Đại hội XIV xác định khó khăn thách thức tác động trực tiếp xây dựng lực lượng vũ trang trong thời gian tới là:", "a": "Nguy cơ tự diễn biến, tự chuyển hóa và âm mưu phi chính trị hóa quân đội, công an.", "flag": false}, {"id": 168, "lesson": "Bài 5", "number": "26", "q": "Quan điểm, nguyên tắc cơ bản nhất trong xây dựng lực lượng vũ trang nhân dân hiện nay là gì?", "a": "Giữ vững và tăng cường sự lãnh đạo của Đảng Cộng sản Việt Nam đối với lực lượng vũ trang.", "flag": false}, {"id": 169, "lesson": "Bài 5", "number": "27", "q": "Xây dựng QĐND, CAND cách mạng, chính quy, tinh nhuệ, hiện đại, nguyên tắc tự lực cường được Đại hội XIV quan tâm nhất là:", "a": "Dựa vào sức mình là chính, phát huy nội lực, tự chủ chiến lược và phát triển công nghiệp quốc phòng.", "flag": false}, {"id": 170, "lesson": "Bài 5", "number": "28", "q": "Phương hướng xây dựng lực lượng vũ trang nhân dân trong giai đoạn mới là:", "a": "QĐND, CAND cách mạng, chính quy, tinh nhuệ, hiện đại; DQTV vững mạnh và rộng khắp; DBĐV hùng hậu.", "flag": false}, {"id": 171, "lesson": "Bài 5", "number": "29", "q": "Nội dung quan trọng nhất trong xây dựng lực lượng vũ trang về chính trị là?", "a": "Xây dựng bản chất giai cấp công nhân, tuyệt đối trung thành với Đảng, Tổ quốc và Nhân dân.", "flag": false}, {"id": 172, "lesson": "Bài 5", "number": "30", "q": "Ai là người thống lĩnh lực lượng vũ trang nhân dân Việt Nam?", "a": "Chủ tịch nước.", "flag": false}, {"id": 173, "lesson": "Bài 5", "number": "31", "q": "Vị trí của lực lượng vũ trang nhân dân Việt Nam được xác định là công cụ bạo lực của Đảng và Nhà nước...", "a": "Công cụ bạo lực sắc bén, lực lượng nòng cốt.", "flag": false}, {"id": 174, "lesson": "Bài 6", "number": "1", "q": "Quốc phòng là công việc giữ nước của một quốc gia, nhằm mục đích:", "a": "Bảo vệ độc lập, chủ quyền, toàn vẹn lãnh thổ và chế độ, giữ vững hòa bình.", "flag": false}, {"id": 175, "lesson": "Bài 6", "number": "2", "q": "Hoạt động an ninh của một quốc gia là để bảo đảm:", "a": "Độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ, chế độ chính trị và sự ổn định, phát triển bền vững.", "flag": false}, {"id": 176, "lesson": "Bài 6", "number": "3", "q": "Kết hợp phát triển kinh tế - xã hội với tăng cường củng cố quốc phòng – an ninh ở nước ta hiện nay là:", "a": "Sự kết hợp chặt chẽ hai nhiệm vụ chiến lược xây dựng và bảo vệ Tổ quốc trong một chỉnh thể thống nhất.", "flag": false}, {"id": 177, "lesson": "Bài 6", "number": "4", "q": "Tác động tích cực của quốc phòng, an ninh đối với kinh tế là:", "a": "Tạo môi trường hòa bình, ổn định tạo điều kiện thuận lợi cho kinh tế phát triển.", "flag": false}, {"id": 178, "lesson": "Bài 6", "number": "5", "q": "Đối với một quốc gia, hoạt động kinh tế là:", "a": "Hoạt động cơ bản, thường xuyên, quyết định sự tồn tại của xã hội và sức mạnh quốc phòng - an ninh.", "flag": false}, {"id": 179, "lesson": "Bài 6", "number": "6", "q": "Tăng cường sự lãnh đạo của Đảng và hiệu lực quản lý của nhà nước... là một trong những nội dung của:", "a": "Nhóm giải pháp chủ yếu thực hiện kết hợp phát triển kinh tế - xã hội với quốc phòng - an ninh.", "flag": false}, {"id": 180, "lesson": "Bài 6", "number": "7", "q": "Một trong những văn bản quy phạm pháp luật là cơ sở để thực hiện kết hợp...", "a": "Nghị định 119/2004/NĐ-CP (và Nghị định 168/2018/NĐ-CP).", "flag": false}, {"id": 181, "lesson": "Bài 6", "number": "8", "q": "Kinh tế, quốc phòng, an ninh có mối quan hệ, tác động qua lại lẫn nhau, trong đó:", "a": "Kinh tế quyết định quốc phòng, an ninh; quốc phòng, an ninh tác động trở lại đối với kinh tế.", "flag": false}, {"id": 182, "lesson": "Bài 6", "number": "9", "q": "Kinh tế quyết định đến quốc phòng, an ninh, trong đó có quyết định đến việc:", "a": "Cung cấp cơ sở vật chất, kỹ thuật, tài chính, vũ khí, trang bị và nhân lực cho QP-AN.", "flag": false}, {"id": 183, "lesson": "Bài 6", "number": "10", "q": "Kinh tế, quốc phòng, an ninh mỗi lĩnh vực đều có quy luật phát triển đặc thù, do đó việc kết hợp... phải thực hiện:", "a": "Một cách toàn diện, chặt chẽ, khoa học, hợp lý, cân đối và hài hòa.", "flag": false}, {"id": 184, "lesson": "Bài 6", "number": "11", "q": "Một trong những kế sách của ông cha ta đã thể hiện kết hợp kinh tế với quốc phòng:", "a": "Ngụ binh ư nông, Động vi binh, tĩnh vi dân.", "flag": false}, {"id": 185, "lesson": "Bài 6", "number": "12", "q": "Một trong những nội dung kinh tế quyết định đến quốc phòng, an ninh là:", "a": "Bản chất của chế độ kinh tế - xã hội quyết định bản chất của quốc phòng, an ninh.", "flag": false}, {"id": 186, "lesson": "Bài 6", "number": "13", "q": "Một trong những nội dung của một số giải pháp thực hiện kết hợp... là:", "a": "Tăng cường sự lãnh đạo của Đảng, nâng cao kiến thức kinh nghiệm, hoàn thiện hệ thống pháp luật, củng cố cơ quan tham mưu.", "flag": false}, {"id": 187, "lesson": "Bài 6", "number": "14", "q": "Ông cha ta xưa kia đã thực hiện kế sách Động vi binh, tĩnh vi dân nghĩa là:", "a": "Khi đất nước có chiến tranh làm người lính đánh giặc, đất nước bình yên làm người dân phát triển kinh tế.", "flag": false}, {"id": 188, "lesson": "Bài 6", "number": "15", "q": "Kinh tế quyết định đến quốc phòng – an ninh, trong đó có nội dung:", "a": "Quyết định tổ chức biên chế của lực lượng vũ trang và trang bị vũ khí kỹ thuật.", "flag": false}, {"id": 189, "lesson": "Bài 6", "number": "16", "q": "Chủ trương của Đảng ta đã từng thực hiện trong kháng chiến chống Pháp về kết hợp kinh tế với quốc phòng, an ninh là:", "a": "Vừa kháng chiến, vừa kiến quốc.", "flag": false}, {"id": 190, "lesson": "Bài 6", "number": "17", "q": "Một trong những nội dung kết hợp phát triển kinh tế xã hội với tăng cường củng cố QP-AN là:", "a": "Thể hiện trong chiến lược phát triển kinh tế - xã hội, theo các vùng lãnh thổ và từng ngành/lĩnh vực kinh tế.", "flag": false}, {"id": 191, "lesson": "Bài 6", "number": "18", "q": "Đối với các vùng kinh tế trọng điểm, việc kết hợp... trong xây dựng, phát triển kinh tế phải nhằm:", "a": "Đáp ứng nhu cầu dân sinh thời bình và chuẩn bị sẵn sàng chi viện cho chiến trường khi xảy ra chiến tranh.", "flag": false}, {"id": 192, "lesson": "Bài 6", "number": "19", "q": "Trong kháng chiến chống Mỹ, Đảng đã đề ra chủ trương: Trong xây dựng kinh tế, phải thấu suốt nhiệm vụ phục vụ quốc phòng... được triển khai:", "a": "Trên phạm vi cả nước.", "flag": false}, {"id": 193, "lesson": "Bài 6", "number": "20", "q": "Kết hợp phát triển KT-XH với QP-AN đối với vùng núi biên giới là cực kỳ quan trọng, vì vùng núi biên giới là:", "a": "Địa bàn chiến lược xung yếu, là phên dậu bảo vệ Tổ quốc nhưng kinh tế còn nhiều khó khăn.", "flag": false}, {"id": 194, "lesson": "Bài 6", "number": "21", "q": "Một trong những nội dung cần tập trung kết hợp phát triển KT-XH với củng cố QP-AN ở vùng biển, đảo là:", "a": "Dân sự hóa biển đảo, phát triển kinh tế biển gắn với bảo vệ chủ quyền, xây dựng lực lượng dân quân biển.", "flag": false}, {"id": 195, "lesson": "Bài 6", "number": "22", "q": "Kết hợp phát triển kinh tế - xã hội với tăng cường củng cố quốc phòng – an ninh trong công nghiệp sẽ làm cơ sở cho:", "a": "Xây dựng tiềm lực cơ sở vật chất, kỹ thuật cho công nghiệp quốc phòng và trang bị cho lực lượng vũ trang.", "flag": false}, {"id": 196, "lesson": "Bài 6", "number": "23", "q": "Một trong những nội dung kết hợp phát triển KT-XH với củng cố QP-AN trong công nghiệp là:", "a": "Phát triển công nghiệp theo hướng lưỡng dụng (vừa sản xuất hàng dân dụng, vừa sản xuất hàng quân sự).", "flag": false}, {"id": 197, "lesson": "Bài 6", "number": "24", "q": "Kết hợp... trong phát triển các vùng lãnh thổ cần phải quan tâm chỉ đạo:", "a": "Quy hoạch tổng thể phát triển kinh tế - xã hội gắn với thế trận phòng thủ vùng và khu vực phòng thủ tỉnh/thành phố.", "flag": false}, {"id": 198, "lesson": "Bài 6", "number": "25", "q": "Kết hợp... trong giao thông vận tải cần phải:", "a": "Xây dựng mạng lưới giao thông lưỡng dụng, bảo đảm tính cơ động lực lượng, phương tiện.", "flag": false}, {"id": 199, "lesson": "Bài 6", "number": "26", "q": "Kết hợp... trong bưu chính viễn thông cần phải:", "a": "Bảo đảm an toàn thông tin, duy trì thông tin liên lạc thông suốt thời bình và thời chiến.", "flag": false}, {"id": 200, "lesson": "Bài 6", "number": "27", "q": "Kết hợp... trong bưu chính viễn thông cần phải:", "a": "Xây dựng hạ tầng viễn thông có tính lưỡng dụng cao, sẵn sàng phục vụ quốc phòng khi có tình huống.", "flag": false}, {"id": 201, "lesson": "Bài 6", "number": "28", "q": "Trong xây dựng cơ bản, việc kết hợp... cần phải thực hiện được yêu cầu:", "a": "Đảm bảo tính lưỡng dụng của công trình, từng bước xây dựng hệ thống công trình ngầm lưỡng dụng.", "flag": false}, {"id": 202, "lesson": "Bài 6", "number": "29", "q": "Kết hợp... trong khoa học, công nghệ và giáo dục cần phải:", "a": "Phối hợp giữa khoa học dân sự và quân sự; đẩy mạnh giáo dục quốc phòng và an ninh.", "flag": false}, {"id": 203, "lesson": "Bài 6", "number": "30", "q": "Trong lĩnh vực y tế, việc kết hợp... cần thực hiện:", "a": "Thực hiện mô hình Quân - Dân y kết hợp, xây dựng kế hoạch động viên y tế dân sự cho quân sự.", "flag": false}, {"id": 204, "lesson": "Bài 6", "number": "31", "q": "Sự phối hợp giữa hoạt động đối ngoại với kinh tế, quốc phòng, an ninh là:", "a": "Giữ nước từ sớm, từ xa, tạo môi trường hòa bình, ổn định để phát triển kinh tế.", "flag": false}, {"id": 205, "lesson": "Bài 6", "number": "32", "q": "Mục tiêu cốt lõi của sự kết hợp kinh tế với quốc phòng an ninh và hoạt động đối ngoại nhằm mục đích?", "a": "Tạo sức mạnh tổng hợp thực hiện 2 nhiệm vụ chiến lược: Xây dựng CNXH và Bảo vệ Tổ quốc XHCN.", "flag": false}, {"id": 206, "lesson": "Bài 6", "number": "33", "q": "Kết hợp kinh tế, quốc phòng, an ninh và đối ngoại là yếu tố quan trọng trong thời kỳ đẩy mạnh hợp tác quốc tế?", "a": "Giữ vững tính độc lập, tự chủ của nền kinh tế và bảo đảm an ninh quốc gia.", "flag": false}, {"id": 207, "lesson": "Bài 6", "number": "34", "q": "Đối với các vùng kinh tế trọng điểm, việc kết hợp... nội dung nào là quan trọng nhất?", "a": "Quy hoạch bố trí phân tán, hạ tầng lưỡng dụng, gắn với quy hoạch khu vực phòng thủ.", "flag": false}, {"id": 208, "lesson": "Bài 6", "number": "35", "q": "Thực hiện giải pháp nào để tạo hành hành pháp lý cho việc quản lý, điều hành kết hợp kinh tế, QP-AN và đối ngoại?", "a": "Thể chế hóa chủ trương bằng hệ thống luật/văn bản quy phạm pháp luật, hoàn thiện quy chế liên ngành.", "flag": false}, {"id": 209, "lesson": "Bài 6", "number": "36", "q": "Trong mối quan hệ giữa kinh tế và quốc phòng thì cách diễn đạt nào sau đây đúng nhất?", "a": "Kinh tế quyết định quốc phòng; quốc phòng tác động trở lại đối với kinh tế.", "flag": false}, {"id": 210, "lesson": "Bài 6", "number": "37", "q": "Kế sách nào sau đây không phải sự kết hợp kinh tế với quốc phòng?", "a": "Các kế sách thuần túy phòng thủ quân sự, không gắn với sản xuất/nông nghiệp.", "flag": false}, {"id": 211, "lesson": "Bài 6", "number": "38", "q": "Phong trào nào sau đây không phải là kết hợp kinh tế với QP?", "a": "Phong trào không chứa nội dung phát triển kinh tế gắn với quốc phòng - an ninh.", "flag": false}, {"id": 212, "lesson": "Bài 6", "number": "39", "q": "Trường hợp nào sau đây là khó khăn trong việc thực hiện kết hợp kinh tế với quốc phòng?", "a": "Ngân sách hạn hẹp; nhận thức chưa đầy đủ; mâu thuẫn giữa nhu cầu đầu tư kinh tế và củng cố QP-AN.", "flag": false}, {"id": 213, "lesson": "Bài 7", "number": "1", "q": "Trong lịch sử, dân tộc Việt Nam luôn bị các thế lực ngoại xâm nhòm ngó, xâm lược vì:", "a": "Việt Nam có vị trí địa lý thuận lợi (vị trí địa chiến lược xung yếu) và tài nguyên phong phú.", "flag": false}, {"id": 214, "lesson": "Bài 7", "number": "2", "q": "Một trong những cơ sở hình thành nghệ thuật quân sự Việt Nam là:", "a": "Truyền thống dựng nước đi đôi với giữ nước của dân tộc.", "flag": false}, {"id": 215, "lesson": "Bài 7", "number": "3", "q": "Đảng ta đã chỉ đạo tiến hành chiến tranh với tinh thần:", "a": "Toàn dân, toàn diện, lâu dài, tự lực cánh sinh, dựa vào sức mình là chính.", "flag": false}, {"id": 216, "lesson": "Bài 7", "number": "4", "q": "Khởi nghĩa của Hai Bà Trưng diễn ra vào:", "a": "Mùa xuân năm 40 sau Công nguyên (năm 40 CN).", "flag": false}, {"id": 217, "lesson": "Bài 7", "number": "5", "q": "Một trong những bài học kinh nghiệm về nghệ thuật quân sự được vận dụng vào sự nghiệp bảo vệ Tổ quốc trong thời kỳ mới là:", "a": "Quán triệt tư tưởng chủ động tiến công, lấy ít địch nhiều, lấy đoản binh thắng trường trận.", "flag": false}, {"id": 218, "lesson": "Bài 7", "number": "6", "q": "Cuộc kháng chiến chống quân Minh do nhà Hồ lãnh đạo thất bại là do:", "a": "Không nhận được sự ủng hộ của dân chúng vì các chính sách không hợp lòng dân, lãnh đạo yếu kém và đường lối kháng chiến bị động.", "flag": false}, {"id": 219, "lesson": "Bài 7", "number": "7", "q": "Trong nghệ thuật kết hợp đấu tranh giữa các mặt trận thì mặt trận chính trị được xác định:", "a": "Cơ sở để tạo ra sức mạnh về quân sự.", "flag": false}, {"id": 220, "lesson": "Bài 7", "number": "8", "q": "Trong nghệ thuật kết hợp đấu tranh giữa các mặt trận thì mặt trận quân sự được xác định:", "a": "Mặt trận quyết định trực tiếp đến thắng lợi của chiến tranh.", "flag": false}, {"id": 221, "lesson": "Bài 7", "number": "9", "q": "Một trong những nội dung chủ yếu của chiến lược quân sự Việt Nam là:", "a": "Xác định kẻ thù, xác định đúng đối tượng tác chiến.", "flag": false}, {"id": 222, "lesson": "Bài 7", "number": "10", "q": "Quy luật của chiến tranh là mạnh được, yếu thua, nhưng ông cha ta đã sớm xác định đúng về sức mạnh chiến tranh, đó là:", "a": "Sức mạnh tổng hợp của nhiều yếu tố, chứ không chỉ dựa trên sự so sánh hơn kém về quân số hay vũ khí.", "flag": false}, {"id": 223, "lesson": "Bài 7", "number": "11", "q": "Trong phương thức tiến hành chiến tranh, Đảng ta đã chỉ đạo:", "a": "Tự lực cánh sinh, đánh lâu dài, dựa vào sức mình là chính.", "flag": false}, {"id": 224, "lesson": "Bài 7", "number": "12", "q": "Chiến thuật thường vận dụng trong thời kỳ đầu của hai cuộc kháng chiến chống Pháp, chống Mỹ là:", "a": "Đánh du kích, đánh vận động và phòng ngự xen kẽ với tiến công.", "flag": false}, {"id": 225, "lesson": "Bài 7", "number": "13", "q": "Trong chiến lược quân sự, Đảng ta đã chỉ đạo phương thức tiến hành chiến tranh là:", "a": "Chiến tranh nhân dân, toàn dân đánh giặc, kết hợp với các hình thức chiến tranh khác nhau.", "flag": false}, {"id": 226, "lesson": "Bài 7", "number": "14", "q": "Cuộc kháng chiến chống quân xâm lược của Triệu Đà do An Dương Vương lãnh đạo thất bại vào những năm:", "a": "Năm 179 TCN.", "flag": false}, {"id": 227, "lesson": "Bài 7", "number": "15", "q": "Khởi nghĩa Tây sơn và các cuộc kháng chiến chống quân Xiêm, quân xâm lược Mãn thanh vào những năm:", "a": "Kháng chiến chống quân Xiêm vào năm 1785 và kháng chiến chống quân Thanh vào năm 1789.", "flag": false}, {"id": 228, "lesson": "Bài 7", "number": "16", "q": "Quốc hiệu đầu tiên của nước ta là gì?", "a": "Xích Quỷ (theo đáp án HP1.pdf) / Văn Lang.", "flag": true}, {"id": 229, "lesson": "Bài 7", "number": "17", "q": "Trong quá trình dựng nước và giữ nước, dân tộc ta đã sớm xây dựng được nền văn hóa truyền thống như thế nào?", "a": "Đa dạng, phong phú, mang đậm bản sắc dân tộc, yêu nước, tinh thần cộng đồng.", "flag": false}, {"id": 230, "lesson": "Bài 7", "number": "18", "q": "Cuộc kháng chiến chống quân xâm lược nào? Do ai lãnh đạo đã bị thất bại dẫn đến đất nước ta bị phong kiến phương Bắc đô hộ hơn 1000 năm ?", "a": "Kháng chiến chống quân xâm lược Triệu Đà, do An Dương Vương lãnh đạo (năm 179 TCN).", "flag": false}, {"id": 231, "lesson": "Bài 7", "number": "19", "q": "Chiến thắng nào giúp nước ta thoát khỏi thời kỳ hơn 1000 năm bị phong kiến phương Bắc đô hộ?", "a": "Chiến thắng sông Bạch Đằng năm 938 (do Ngô Quyền lãnh đạo).", "flag": false}, {"id": 232, "lesson": "Bài 7", "number": "20", "q": "Ai là người thực hiện kế sách Tiên phát chế nhân trong lịch sử đấu tranh chống ngoại xâm của dân tộc ta?", "a": "Lý Thường Kiệt (kháng chiến chống Tống năm 1075 - 1077).", "flag": false}, {"id": 233, "lesson": "Bài 7", "number": "21", "q": "Trước sức mạnh của quân Nguyên Mông triều đình nhà Trần đã thực hiện kế sách gì?", "a": "Vườn không nhà trống (thanh dã) kết hợp với chiến lược tiến thoái linh hoạt.", "flag": false}, {"id": 234, "lesson": "Bài 7", "number": "22", "q": "Triều đại nào tổ chức Hội nghị Diên Hồng tại kinh đô Thăng Long nhằm hiệu triệu tinh thần chống giặc ngoại xâm của Nhân dân ta?", "a": "Triều đại Nhà Trần.", "flag": false}, {"id": 235, "lesson": "Bài 7", "number": "23", "q": "Nguyễn Huệ đã đập tan ý đồ bán nước của Nguyễn Ánh và âm mưu xâm lược của quân Xiêm trong trận quyết chiến chiến lược nào?", "a": "Trận Rạch Gầm - Xoài Mút (năm 1785).", "flag": false}, {"id": 236, "lesson": "Bài 7", "number": "24", "q": "Những yếu tố nào đã tác động đến việc hình thành nghệ thuật đánh giặc của ông cha ta?", "a": "Điều kiện địa lý, kinh tế - xã hội, văn hóa và truyền thống đánh giặc giữ nước.", "flag": false}, {"id": 237, "lesson": "Bài 7", "number": "25", "q": "Đâu là nét đặc sắc và tất yếu trong nghệ thuật quân sự của ông cha ta?", "a": "Lấy nhỏ đánh lớn, lấy ít địch nhiều, lấy yếu chống mạnh.", "flag": false}, {"id": 238, "lesson": "Bài 7", "number": "26", "q": "Đâu là nét độc đáo trong nghệ thuật quân sự của ông cha ta, được thể hiện cả trong khởi nghĩa và chiến tranh giải phóng?", "a": "Nghệ thuật chiến tranh nhân dân, thực hiện toàn dân đánh giặc.", "flag": false}, {"id": 239, "lesson": "Bài 7", "number": "27", "q": "Tư tưởng chỉ đạo tác chiến nào được ông cha ta coi như một quy luật để giành thắng lợi trong suốt quá trình chuẩn bị và thực hành chiến tranh?", "a": "Tích cực, chủ động tiến công (kiên quyết không ngừng thế tiến công).", "flag": false}, {"id": 240, "lesson": "Bài 7", "number": "28", "q": "Trong nghệ thuật đánh giặc của ông cha ta dùng mưu để đánh giặc được hiểu như thế nào?", "a": "Dùng mưu trí, lừa địch, đánh vào chỗ yếu/bất ngờ của kẻ thù.", "flag": false}, {"id": 241, "lesson": "Bài 7", "number": "29", "q": "Trong nghệ thuật đánh giặc của ông cha ta dùng kế để đánh giặc được hiểu như thế nào?", "a": "Dàn xếp thế trận, tạo bẫy, buộc địch hành động theo ý định của ta.", "flag": false}, {"id": 242, "lesson": "Bài 7", "number": "30", "q": "Trong nghệ thuật kết hợp đấu tranh giữa các Mặt trận quân sự, chính trị, ngoại giao và binh vận thì Mặt trận nào là cơ sở để tạo ra sức mạnh quân sự ?", "a": "Mặt trận chính trị.", "flag": false}, {"id": 243, "lesson": "Bài 7", "number": "31", "q": "Lý Thường Kiệt sử dụng biện pháp tiên phát chế nhân nghĩa là?", "a": "Chủ động tiến công trước để khống chế, đẩy kẻ thù vào thế bị động.", "flag": false}, {"id": 244, "lesson": "Bài 7", "number": "32", "q": "Chiến dịch nào sau đây là chiến dịch phản công?", "a": "Chiến dịch Việt Bắc Thu - Đông 1947.", "flag": false}, {"id": 245, "lesson": "Bài 7", "number": "33", "q": "Một trong những nội dung nghệ thuật đánh giặc của ông cha ta là kết hợp đấu tranh giữa các mặt trận?", "a": "Kết hợp đấu tranh quân sự, chính trị, ngoại giao và binh vận.", "flag": false}, {"id": 246, "lesson": "Bài 7", "number": "34", "q": "Một trong những cơ sở hình thành nghệ thuật quân sự Việt Nam là gì?", "a": "Truyền thống yêu nước, đoàn kết và truyền thống đánh giặc giữ nước của dân tộc.", "flag": false}, {"id": 247, "lesson": "Bài 7", "number": "35", "q": "Khi đế quốc Mỹ tiến hành chiến tranh xâm lược Việt Nam, Đảng ta nhận định?", "a": "Đế quốc Mỹ là kẻ thù trực tiếp, nguy hiểm nhất của nhân dân Việt Nam.", "flag": false}, {"id": 248, "lesson": "Bài 7", "number": "36", "q": "Trong chiến dịch Điện Biên Phủ, chúng ta đã thay đổi?", "a": "Thay đổi phương châm tác chiến từ Đánh nhanh, thắng nhanh sang Đánh chắc, tiến chắc.", "flag": false}, {"id": 249, "lesson": "Bài 7", "number": "37", "q": "Mặt trận binh vận có ý nghĩa là?", "a": "Làm tan rã hàng ngũ kẻ thù, hạn chế thấp nhất tổn thất của ta.", "flag": false}, {"id": 250, "lesson": "Bài 8", "number": "1", "q": "Lãnh thổ quốc gia là:", "a": "Một phần của Trái Đất thuộc chủ quyền hoàn toàn, đầy đủ và tuyệt đối của một quốc gia.", "flag": false}, {"id": 251, "lesson": "Bài 8", "number": "2", "q": "Lãnh hải của Việt Nam là:", "a": "Vùng biển thuộc chủ quyền quốc gia, rộng 12 hải lý tính từ đường cơ sở.", "flag": false}, {"id": 252, "lesson": "Bài 8", "number": "3", "q": "Nội thủy của lãnh thổ quốc gia là:", "a": "Toàn bộ vùng nước tiếp giáp với bờ biển và nằm ở phía trong đường cơ sở.", "flag": false}, {"id": 253, "lesson": "Bài 8", "number": "4", "q": "Xây dựng và bảo vệ biên giới quốc gia là một nội dung của:", "a": "Sự nghiệp xây dựng và bảo vệ Tổ quốc Việt Nam xã hội chủ nghĩa.", "flag": false}, {"id": 254, "lesson": "Bài 8", "number": "5", "q": "Biên giới quốc gia Việt Nam trên đất liền là đường phân định:", "a": "Được hoạch định và đánh dấu trên thực địa bằng hệ thống mốc quốc giới.", "flag": false}, {"id": 255, "lesson": "Bài 8", "number": "6", "q": "Vùng đặc quyền kinh tế của Việt Nam trong vùng biển có chiều rộng:", "a": "200 hải lý tính từ đường cơ sở.", "flag": false}, {"id": 256, "lesson": "Bài 8", "number": "7", "q": "Chủ quyền quốc gia là:", "a": "Quyền làm chủ đối với quốc gia, là thuộc tính chính trị - pháp lý không thể tách rời khỏi quốc gia.", "flag": false}, {"id": 257, "lesson": "Bài 8", "number": "8", "q": "Chủ quyền lãnh thổ quốc gia là:", "a": "Quyền lực độc lập, làm chủ của quốc gia đối với phạm vi lãnh thổ của mình.", "flag": false}, {"id": 258, "lesson": "Bài 8", "number": "9", "q": "Biên giới quốc gia trên biển của Việt Nam là:", "a": "Ranh giới ngoài của lãnh hải (cách đường cơ sở 12 hải lý, song song với đường cơ sở).", "flag": false}, {"id": 259, "lesson": "Bài 8", "number": "10", "q": "Một trong những quan điểm của đảng về xây dựng và bảo vệ chủ quyền lãnh thổ, biên giới quốc gia là:", "a": "Xây dựng biên giới hòa bình, hữu nghị, ổn định.", "flag": false}, {"id": 260, "lesson": "Bài 8", "number": "11", "q": "Xây dựng và bảo vệ chủ quyền lãnh thổ quốc gia là:", "a": "Xác lập và bảo vệ quyền lập pháp, hành pháp, tư pháp về mọi mặt trong phạm vi lãnh thổ.", "flag": false}, {"id": 261, "lesson": "Bài 8", "number": "12", "q": "Nội dung nào sau đây là một trong những nội dung xây dựng và bảo vệ chủ quyền lãnh thổ quốc gia là:", "a": "Xây dựng và phát triển mọi mặt chính trị, kinh tế, văn hóa, xã hội, đối ngoại, quốc phòng và an ninh của đất nước.", "flag": false}, {"id": 262, "lesson": "Bài 8", "number": "13", "q": "Bảo vệ chủ quyền lãnh thổ quốc gia là:", "a": "Việc bảo vệ toàn vẹn lãnh thổ và các quyền tối cao của Nhà nước đối với vùng lãnh thổ đó, không để bất kỳ quốc gia hay thế lực nào can thiệp.", "flag": false}, {"id": 263, "lesson": "Bài 8", "number": "14", "q": "Một trong những nội dung xây dựng và bảo vệ chủ quyền lãnh thổ quốc gia là:", "a": "Tăng cường hợp tác nhiều mặt nhằm xây dựng biên giới hòa bình, hữu nghị, ổn định lâu dài.", "flag": false}, {"id": 264, "lesson": "Bài 8", "number": "15", "q": "Nội dung nào sau đây là một trong những nội dung xây dựng và bảo vệ chủ quyền lãnh thổ quốc gia là:", "a": "Xác lập và bảo vệ quyền lập pháp, hành pháp, tư pháp trên mọi mặt.", "flag": false}, {"id": 265, "lesson": "Bài 8", "number": "16", "q": "Làm tốt nhiệm vụ xây dựng và bảo vệ chủ quyền lãnh thổ quốc gia là:", "a": "Sự nghiệp của toàn dân, dưới sự lãnh đạo của Đảng và quản lý của Nhà nước, với lực lượng vũ trang làm nòng cốt.", "flag": false}, {"id": 266, "lesson": "Bài 8", "number": "17", "q": "Biên giới quốc gia của Việt Nam là:", "a": "Đường và mặt phẳng thẳng đứng theo đường đó để xác định giới hạn lãnh thổ đất liền, các đảo, các quần đảo, vùng biển, lòng đất, vùng trời.", "flag": false}, {"id": 267, "lesson": "Bài 8", "number": "18", "q": "Theo Luật Biên giới quốc gia... thì xây dựng, quản lý, bảo vệ biên giới quốc gia... là:", "a": "Sự nghiệp của toàn dân do Nhà nước thống nhất quản lý.", "flag": false}, {"id": 268, "lesson": "Bài 8", "number": "19", "q": "Một trong những nội dung xây dựng và bảo vệ biên giới quốc gia là:", "a": "Xây dựng thế trận biên phòng toàn dân vững chắc.", "flag": false}, {"id": 269, "lesson": "Bài 8", "number": "20", "q": "Một trong những nội dung xây dựng và bảo vệ biên giới quốc gia là:", "a": "Ưu tiên đầu tư xây dựng khu vực biên giới vững mạnh toàn diện về chính trị, kinh tế - xã hội, QP-AN.", "flag": false}, {"id": 270, "lesson": "Bài 8", "number": "21", "q": "Một trong những nội dung xây dựng và bảo vệ biên giới quốc gia là:", "a": "Bảo vệ toàn vẹn lãnh thổ của Tổ quốc; bảo vệ tài nguyên, môi sinh, môi trường và lợi ích quốc gia ở khu vực biên giới.", "flag": false}, {"id": 271, "lesson": "Bài 8", "number": "22", "q": "Xây dựng, quản lý, bảo vệ biên giới quốc gia... được quy định trong bộ luật nào?", "a": "Luật Biên giới quốc gia năm 2003.", "flag": false}, {"id": 272, "lesson": "Bài 8", "number": "23", "q": "Theo luật pháp quốc tế, việc Trung Quốc chiếm giữ quần đảo Hoàng Sa của Việt Nam là vi phạm về:", "a": "Nguyên tắc chủ quyền toàn vẹn lãnh thổ.", "flag": false}, {"id": 273, "lesson": "Bài 8", "number": "24", "q": "Quan điểm xây dựng biên giới hòa bình hữu nghị, ổn định là:", "a": "Quan điểm nhất quán, phù hợp với lợi ích, luật pháp của Việt Nam và công ước quốc tế.", "flag": false}, {"id": 274, "lesson": "Bài 8", "number": "25", "q": "Quan điểm của Đảng và Nhà nước ta trong giải quyết các vấn đề tranh chấp lãnh thổ, biên giới là:", "a": "Thông qua đàm phán hòa bình, tôn trọng độc lập, chủ quyền toàn vẹn lãnh thổ của nhau.", "flag": false}, {"id": 275, "lesson": "Bài 8", "number": "26", "q": "Theo luật pháp Quốc tế hiện đại, tất cả các quốc gia bình đẳng về?", "a": "Mặt chủ quyền pháp lý.", "flag": false}, {"id": 276, "lesson": "Bài 8", "number": "27", "q": "Quốc gia Việt Nam là thực thể pháp lý bao gồm những yếu tố nào cấu thành?", "a": "Lãnh thổ, dân cư, quyền lực công cộng (chính quyền).", "flag": false}, {"id": 277, "lesson": "Bài 8", "number": "28", "q": "Xây dựng và bảo vệ chủ quyền lãnh thổ biên giới quốc gia là sự nghiệp của ai?", "a": "Toàn dân.", "flag": false}, {"id": 278, "lesson": "Bài 8", "number": "29", "q": "Việt Nam có bờ biển dài khoảng bao nhiêu km?", "a": "Khoảng 3.260 km.", "flag": false}, {"id": 279, "lesson": "Bài 8", "number": "30", "q": "Theo về nguyên tắc tổ chức sắp xếp lại đơn vị hành chính cấp xã, chuyển các huyện đảo... thành:", "a": "Đơn vị hành chính cấp xã (Xã đảo, Phường đảo, Đặc khu).", "flag": false}, {"id": 280, "lesson": "Bài 8", "number": "31", "q": "Theo quy ước quốc tế, 1 hải lý bằng bao nhiêu mét?", "a": "1.852 mét.", "flag": false}, {"id": 281, "lesson": "Bài 8", "number": "32", "q": "Thềm lục địa của Việt Nam là vùng đáy biển và lòng đất dưới đáy biển... cho đến:", "a": "Mép ngoài của rìa lục địa (không vượt quá 200 hải lý, mở rộng tối đa không quá 350 hải lý).", "flag": false}, {"id": 282, "lesson": "Bài 8", "number": "33", "q": "Quốc gia nào chưa ký kết tham gia Công ước Liên Hợp Quốc về Luật biển 1982 (UNCLOS 1982)?", "a": "Mỹ (Hoa Kỳ).", "flag": false}, {"id": 283, "lesson": "Bài 8", "number": "34", "q": "Một trong những quan điểm của Đảng và Nhà nước ta về biên giới và quản lý, bảo vệ biên giới quốc gia là:", "a": "Xây dựng biên giới hòa bình, hữu nghị; giải quyết tranh chấp bằng đàm phán hòa bình dựa trên luật pháp quốc tế.", "flag": false}, {"id": 284, "lesson": "Bài 9", "number": "1", "q": "Là lực lượng vũ trang quần chúng không thoát ly sản xuất, công tác, được tổ chức ở đâu gọi là dân quân?", "a": "Địa phương (xã, phường, thị trấn).", "flag": false}, {"id": 285, "lesson": "Bài 9", "number": "2", "q": "Là lực lượng vũ trang quần chúng không thoát ly sản xuất, công tác, được tổ chức ở đâu gọi là tự vệ?", "a": "Cơ quan nhà nước, tổ chức chính trị - xã hội, đơn vị sự nghiệp, tổ chức kinh tế.", "flag": false}, {"id": 286, "lesson": "Bài 9", "number": "3", "q": "Điều 6. Luật dân quân tự vệ 2019 qui định có mấy thành phần:", "a": "5 thành phần (DQTV tại chỗ, DQTV cơ động, Dân quân thường trực, DQTV biển, DQTV binh chủng).", "flag": false}, {"id": 287, "lesson": "Bài 9", "number": "4", "q": "Dân quân tự vệ tại chỗ là gì?", "a": "Lực lượng làm nhiệm vụ ở thôn, ấp, bản, làng, buôn, phum, sóc, tổ dân phố và cơ quan, tổ chức.", "flag": false}, {"id": 288, "lesson": "Bài 9", "number": "5", "q": "Dân quân tự vệ cơ động là gì?", "a": "Lực lượng cơ động làm nhiệm vụ trên các địa bàn theo quyết định của cấp có thẩm quyền.", "flag": false}, {"id": 289, "lesson": "Bài 9", "number": "6", "q": "Dân quân thường trực là gì?", "a": "Lực lượng thường trực làm nhiệm vụ tại các địa bàn trọng điểm về quốc phòng.", "flag": false}, {"id": 290, "lesson": "Bài 9", "number": "7", "q": "Dân quân tự vệ biển là gì?", "a": "Lực lượng làm nhiệm vụ trên các hải đảo, vùng biển Việt Nam.", "flag": false}, {"id": 291, "lesson": "Bài 9", "number": "8", "q": "Vị trí, chức năng của Dân quân tự vệ được qui định như thế nào?", "a": "Là thành phần của Lực lượng vũ trang nhân dân, là lực lượng chiến lược trong chiến tranh nhân dân, quốc phòng toàn dân.", "flag": false}, {"id": 292, "lesson": "Bài 9", "number": "9", "q": "Điều 5 Luật dân quân tự vệ 2019 qui định DQTV có mấy nhiệm vụ?", "a": "07 nhiệm vụ.", "flag": false}, {"id": 293, "lesson": "Bài 9", "number": "10", "q": "Một trong những vị trí vai trò của dân quân tự vệ là:", "a": "Lực lượng chiến lược trong chiến tranh nhân dân, quốc phòng toàn dân.", "flag": false}, {"id": 294, "lesson": "Bài 9", "number": "11", "q": "Một trong những vị trí vai trò của dân quân tự vệ là:", "a": "Lực lượng trực tiếp bảo vệ Đảng, chính quyền, tính mạng, tài sản của nhân dân ở cơ sở.", "flag": false}, {"id": 295, "lesson": "Bài 9", "number": "12", "q": "Nội dung nào sau đây là một trong những nội dung của phương châm xây dựng dân quân tự vệ hiện nay?", "a": "Vững mạnh, rộng khắp, coi trọng chất lượng là chính.", "flag": false}, {"id": 296, "lesson": "Bài 9", "number": "13", "q": "Quân nhân dự bị động viên được đăng ký, quản lý tại:", "a": "Nơi cư trú (Ban Chỉ huy quân sự cấp xã/huyện).", "flag": false}, {"id": 297, "lesson": "Bài 9", "number": "14", "q": "Xây dựng lực lượng dự bị động viên là nhiệm vụ của:", "a": "Toàn Đảng, toàn quân, toàn dân, của cả hệ thống chính trị.", "flag": false}, {"id": 298, "lesson": "Bài 9", "number": "15", "q": "Nội dung nào sau đây là một trong những biện pháp xây dựng lực lượng dân quân tự vệ?", "a": "Xây dựng lực lượng Dân quân tự vệ coi trọng chất lượng là chính.", "flag": false}, {"id": 299, "lesson": "Bài 9", "number": "16", "q": "Một trong những biện pháp xây dựng lực lượng dân quân tự vệ hiện nay là:", "a": "Tăng cường giáo dục chính trị, pháp luật, huấn luyện quân sự và nâng cao chất lượng công tác quản lý.", "flag": false}, {"id": 300, "lesson": "Bài 9", "number": "17", "q": "Ngày nào hằng năm được lấy là ngày truyền thống của Dân quân tự vệ?", "a": "Ngày 28/03 (28/03/1935).", "flag": false}, {"id": 301, "lesson": "Bài 9", "number": "18", "q": "Độ tuổi tham gia Dân quân tự vệ được qui định như thế nào?", "a": "Nam từ đủ 18 đến hết 45 tuổi; Nữ từ đủ 18 đến hết 40 tuổi.", "flag": false}, {"id": 302, "lesson": "Bài 9", "number": "19", "q": "Nếu tình nguyện tham gia Dân quân tự vệ thì độ tuổi có thể kéo dài đến bao nhiêu?", "a": "Nam đến hết 50 tuổi; Nữ đến hết 45 tuổi.", "flag": false}, {"id": 303, "lesson": "Bài 9", "number": "20", "q": "Bảo đảm số lượng đủ, chất lượng cao, xây dựng toàn diện nhưng có trọng tâm, trọng điểm là:", "a": "Quan điểm / nhiệm vụ xây dựng lực lượng dự bị động viên.", "flag": true}, {"id": 304, "lesson": "Bài 9", "number": "21", "q": "Một trong những nguyên tắc sắp xếp quân nhân dự bị vào các đơn vị dự bị động viên là:", "a": "Theo trình độ chuyên môn quân sự, hạng khen thưởng, nhóm tuổi và địa bàn cư trú.", "flag": false}, {"id": 305, "lesson": "Bài 9", "number": "22", "q": "Việc bảo đảm vật chất, kinh phí xây dựng lực lượng dự bị động viên hàng năm do:", "a": "Trách nhiệm của Ngân sách nhà nước.", "flag": false}, {"id": 306, "lesson": "Bài 9", "number": "23", "q": "Một trong những nội dung xây dựng lực lượng dự bị động viên là:", "a": "Tạo nguồn, đăng ký, quản lý lực lượng dự bị động viên.", "flag": false}, {"id": 307, "lesson": "Bài 9", "number": "24", "q": "Phương tiện kỹ thuật của lực lượng dự bị động viên thường gồm:", "a": "Các loại phương tiện giao thông, xây dựng, xếp dỡ, thông tin liên lạc, thiết bị y tế.", "flag": false}, {"id": 308, "lesson": "Bài 9", "number": "25", "q": "Nguyên tắc lãnh đạo của Đảng đối với lực lượng dự bị động viên nhằm mục đích:", "a": "Đảm bảo lực lượng luôn được xây dựng vững mạnh về mọi mặt, sẵn sàng chiến đấu cao.", "flag": false}, {"id": 309, "lesson": "Bài 9", "number": "26", "q": "Cấp xã có thể tổ chức đơn vị Dân quân Cơ động cao nhất đến:", "a": "Cấp Trung đội.", "flag": false}, {"id": 310, "lesson": "Bài 9", "number": "27", "q": "Quân nhân dự bị gồm:", "a": "Sĩ quan dự bị, quân nhân chuyên nghiệp dự bị, hạ sĩ quan và binh sĩ dự bị.", "flag": false}, {"id": 311, "lesson": "Bài 9", "number": "28", "q": "Tạo nguồn lực lượng dự bị động viên:", "a": "Dựa vào quân nhân hoàn thành nghĩa vụ quân sự và tuyển chọn công dân/sinh viên tốt nghiệp đại học.", "flag": false}, {"id": 312, "lesson": "Bài 9", "number": "29", "q": "Xây dựng dân quân tự vệ vững mạnh, rộng khắp... Đảng ta xác định coi trọng lực lượng nào?", "a": "Coi trọng Dân quân tự vệ biển và DQTV ở các địa bàn trọng điểm.", "flag": false}, {"id": 313, "lesson": "Bài 9", "number": "30", "q": "Thời hạn thực hiện nghĩa vụ tham gia Dân quân thường trực là mấy năm?", "a": "02 năm (24 tháng).", "flag": false}, {"id": 314, "lesson": "Bài 9", "number": "31", "q": "Lực lượng dự bị động viên gồm những thành phần nào?", "a": "Quân nhân dự bị và Phương tiện kỹ thuật dự bị.", "flag": false}, {"id": 315, "lesson": "Bài 9", "number": "32", "q": "Lực lượng dự bị động viên thuộc thành phần nào của Lực lượng vũ trang nhân dân?", "a": "Thuộc Quân đội nhân dân Việt Nam (Bộ phận dự bị của QĐND).", "flag": false}, {"id": 316, "lesson": "Bài 9", "number": "33", "q": "Ngụ binh ư nông dùng để chỉ lực lượng nào?", "a": "Lực lượng dự bị động viên.", "flag": false}, {"id": 317, "lesson": "Bài 9", "number": "34", "q": "Đâu là một trong những quan điểm nguyên tắc xây dựng lực lượng Dự bị động viên?", "a": "Đặt dưới sự lãnh đạo tuyệt đối, trực tiếp về mọi mặt của Đảng; bảo đảm số lượng đủ, chất lượng cao.", "flag": false}, {"id": 318, "lesson": "Bài 9", "number": "35", "q": "Lực lượng dự bị động viên gồm những thành phần nào sau đây là đúng nhất?", "a": "Quân nhân dự bị (Sĩ quan, QNCN, HSQ-BS dự bị) và Phương tiện kỹ thuật dự bị.", "flag": false}, {"id": 319, "lesson": "Bài 9", "number": "36", "q": "Thường xuyên củng cố kiện toàn, bồi dưỡng cơ quan và đội ngũ cán bộ... là?", "a": "Thuộc nhóm biện pháp xây dựng lực lượng dự bị động viên.", "flag": false}, {"id": 320, "lesson": "Bài 10", "number": "1", "q": "Là hình thức hoạt động tự giác, có tổ chức của đông đảo quần chúng nhân dân tham gia xây dựng, quản lý nền an ninh, trật tự...", "a": "Khái niệm Phong trào toàn dân bảo vệ an ninh Tổ quốc.", "flag": false}, {"id": 321, "lesson": "Bài 10", "number": "2", "q": "Mục đích xây dựng phong trào toàn dân bảo vệ an ninh Tổ quốc?", "a": "Xây dựng, quản lý nền an ninh trật tự, chủ động phòng ngừa, phát hiện, ngăn chặn tội phạm.", "flag": false}, {"id": 322, "lesson": "Bài 10", "number": "3", "q": "Phong trào toàn dân bảo vệ an ninh Tổ quốc thu hút đông đảo quần chúng nhân dân tự giác tham gia...", "a": "Đặc điểm của phong trào.", "flag": false}, {"id": 323, "lesson": "Bài 10", "number": "4", "q": "Phong trào toàn dân bảo vệ an ninh Tổ quốc góp phần huy động, tập hợp sức mạnh từ quần chúng nhân dân...", "a": "Vai trò / Vị trí, tác dụng của phong trào.", "flag": true}, {"id": 324, "lesson": "Bài 10", "number": "5", "q": "Nghị định của Chính phủ về phối hợp giữa Bộ Công an và Bộ Quốc phòng trong thực hiện nhiệm vụ bảo vệ ANQG, TTATXH...", "a": "Nghị định 03/2019/NĐ-CP (ngày 05/09/2019).", "flag": false}, {"id": 325, "lesson": "Bài 10", "number": "6", "q": "Phong trao toàn dân bảo vệ ANTQ do cơ quan nào tổ chức ?", "a": "Bộ Công an (dưới sự lãnh đạo của Đảng và quản lý của Nhà nước).", "flag": false}, {"id": 326, "lesson": "Bài 10", "number": "7", "q": "Ngày Hội toàn dân bảo vệ ANTQ là ngày tháng nào?", "a": "Ngày 19/8 hàng năm (Ngày 19 tháng 8).", "flag": false}, {"id": 327, "lesson": "Bài 10", "number": "8", "q": "Quán triệt quan điểm lấy dân làm gốc trong xây dựng phong trào toàn dân bảo vệ an ninh Tổ quốc. Thuộc nội dung nào?", "a": "Quan điểm chỉ đạo xây dựng phong trào.", "flag": false}, {"id": 328, "lesson": "Bài 10", "number": "9", "q": "Xây dựng, phát triển phong trào toàn dân bảo vệ an ninh Tổ quốc là nhiệm vụ của toàn Đảng, toàn dân, cả hệ thống chính trị...", "a": "Chủ thể / Trách nhiệm xây dựng phong trào.", "flag": true}, {"id": 329, "lesson": "Bài 10", "number": "10", "q": "Vận động xây dựng phong trào toàn dân bảo vệ an ninh Tổ quốc có bao nhiêu nội dung?", "a": "07 nội dung cơ bản.", "flag": false}, {"id": 330, "lesson": "Bài 10", "number": "11", "q": "Vận động quần chúng nhận thức đúng, tự giác chấp hành nghiêm túc mọi chủ trương, đường lối của Đảng, pháp luật...", "a": "Nội dung công tác tuyên truyền, vận động.", "flag": false}, {"id": 331, "lesson": "Bài 10", "number": "12", "q": "Nắm tình hình xây dựng phong trào toàn dân bảo vệ an ninh Tổ quốc có bao nhiêu nội dung?", "a": "04 nội dung.", "flag": false}, {"id": 332, "lesson": "Bài 10", "number": "13", "q": "Phương pháp nắm tình hình xây dựng phong trào toàn dân bảo vệ an ninh Tổ quốc có bao nhiêu bước?", "a": "04 bước.", "flag": false}, {"id": 333, "lesson": "Bài 10", "number": "14", "q": "Triệt để khai thác sử dụng phương tiện thông tin đại chúng và các loại hình văn hóa, giáo dục, nghệ thuật...", "a": "Hình thức, biện pháp tuyên truyền, giáo dục.", "flag": false}, {"id": 334, "lesson": "Bài 10", "number": "15", "q": "Những tổ chức nào là tổ chức nòng cốt trong phong trào toàn dân bảo vệ ANTQ?", "a": "Công an xã/phường, Bảo vệ dân phố, Dân phòng, Đội Cờ đỏ, các Ban/Tổ an ninh tự quản.", "flag": false}, {"id": 335, "lesson": "Bài 10", "number": "16", "q": "Xây dựng phong trào toàn dân bảo vệ an ninh Tổ quốc gắn liền với tấn công, trấn áp tội phạm...", "a": "Biện pháp xây dựng phong trào toàn dân bảo vệ ANTQ.", "flag": false}, {"id": 336, "lesson": "Bài 10", "number": "17", "q": "Phong trào toàn dân bảo vệ an ninh Tổ quốc có bao nhiêu đặc điểm chính?", "a": "03 đặc điểm chính.", "flag": false}, {"id": 337, "lesson": "Bài 10", "number": "18", "q": "Một trong những vị trí, tác dụng của phong trào toàn dân bảo vệ an ninh Tổ quốc là:", "a": "Là nền tảng, cơ sở để xây dựng thế trận an ninh nhân dân vững chắc.", "flag": false}, {"id": 338, "lesson": "Bài 10", "number": "19", "q": "Mục đích của phong trào toàn dân bảo vệ an ninh Tổ quốc là:", "a": "Huy động sức mạnh quần chúng bảo vệ an ninh quốc gia, giữ gìn trật tự an toàn xã hội ở cơ sở.", "flag": false}, {"id": 339, "lesson": "Bài 10", "number": "20", "q": "Vận động toàn dân tích cực tham gia chương trình quốc gia phòng chống tội phạm là:", "a": "Một trong những nội dung cơ bản của phong trào toàn dân bảo vệ an ninh Tổ quốc.", "flag": false}, {"id": 340, "lesson": "Bài 10", "number": "21", "q": "Một trong những nội dung cơ bản của công tác xây dựng phong trào toàn dân bảo vệ an ninh Tổ quốc là:", "a": "Tuyên truyền, giáo dục nâng cao cảnh giác cách mạng, xây dựng lực lượng nòng cốt ở cơ sở.", "flag": false}, {"id": 341, "lesson": "Bài 10", "number": "22", "q": "Tham gia xây dựng tổ chức Đảng, chính quyền, đoàn thể quần chúng tại cơ sở vững mạnh là:", "a": "Một trong những nội dung cơ bản của công tác xây dựng phong trào toàn dân bảo vệ ANTQ.", "flag": false}, {"id": 342, "lesson": "Bài 10", "number": "23", "q": "Một trong những vị trí, tác dụng của phong trào toàn dân bảo vệ an ninh Tổ quốc là:", "a": "Là phương thức căn bản để phòng ngừa xã hội đối với tội phạm và vi phạm pháp luật.", "flag": false}, {"id": 343, "lesson": "Bài 10", "number": "24", "q": "Một trong những nội dung cơ bản của công tác xây dựng phong trào toàn dân bảo vệ an ninh Tổ quốc là:", "a": "Vận động nhân dân tham gia phòng ngừa, phát hiện, tố giác tội phạm.", "flag": false}, {"id": 344, "lesson": "Bài 10", "number": "25", "q": "Một trong những nội dung cơ bản của công tác xây dựng phòng trào toàn dân bảo vệ an ninh Tổ quốc là:", "a": "Xây dựng và nhân rộng các mô hình, tổ chức quần chúng tự quản về an ninh trật tự.", "flag": false}, {"id": 345, "lesson": "Bài 10", "number": "26", "q": "Đội Cờ đỏ là tổ chức quần chúng nòng cốt làm nhiệm vụ an ninh trật tự trong nhà trường có chức năng:", "a": "Tự quản, phối hợp bảo vệ an ninh trật tự và kỷ luật trong nhà trường.", "flag": false}, {"id": 346, "lesson": "Bài 10", "number": "27", "q": "Bảo vệ bí mật nhà nước là nội dung của:", "a": "Bảo vệ an ninh quốc gia / An ninh chính trị nội bộ.", "flag": true}, {"id": 347, "lesson": "Bài 10", "number": "28", "q": "Nội dung bảo vệ an ninh Lãnh thổ:", "a": "Bảo vệ tính nguyên vẹn, bất khả xâm phạm về chủ quyền lãnh thổ, biên giới quốc gia, vùng trời, vùng biển.", "flag": false}, {"id": 348, "lesson": "Bài 10", "number": "29", "q": "Một trong những đặc điểm của cuộc đấu tranh bảo vệ an ninh Tổ quốc là:", "a": "Diễn ra gay gao, phức tạp, quyết liệt, âm thầm, lâu dài và mang tính giai cấp sâu sắc.", "flag": false}, {"id": 349, "lesson": "Bài 10", "number": "30", "q": "Phong trào Ngũ gia liên bảo là phong trào hành động cách mạng của nhân dân trong thời kì nào?", "a": "Thời kỳ kháng chiến chống Pháp / chống Mỹ.", "flag": true}, {"id": 350, "lesson": "Bài 10", "number": "31", "q": "Mục đích của phong trào toàn dân bảo vệ an ninh, trật tự là gì?", "a": "Giữ vững an ninh quốc gia, bảo đảm trật tự an toàn xã hội, phục vụ phát triển kinh tế - xã hội.", "flag": false}, {"id": 351, "lesson": "Bài 11", "number": "1", "q": "An ninh quốc gia là?", "a": "Sự ổn định, phát triển bền vững của chế độ XHCN và Nhà nước CHXHCN Việt Nam, sự bất khả xâm phạm độc lập, chủ quyền.", "flag": false}, {"id": 352, "lesson": "Bài 11", "number": "2", "q": "Bảo vệ an ninh quốc gia là?", "a": "Phòng ngừa, phát hiện, ngăn chặn, đấu tranh làm thất bại các hoạt động xâm phạm an ninh quốc gia.", "flag": false}, {"id": 353, "lesson": "Bài 11", "number": "3", "q": "Hoạt động xâm phạm an ninh quốc gia là?", "a": "Những hành vi xâm phạm chế độ chính trị, kinh tế, văn hóa, quốc phòng, đối ngoại, độc lập, chủ quyền, toàn vẹn lãnh thổ.", "flag": false}, {"id": 354, "lesson": "Bài 11", "number": "4", "q": "Nguy cơ đe doạ an ninh quốc gia là?", "a": "Các nhân tố bên trong và bên ngoài có khả năng gây tổn hại đến an ninh quốc gia.", "flag": false}, {"id": 355, "lesson": "Bài 11", "number": "5", "q": "Trách nhiệm, nghĩa vụ bảo vệ an ninh quốc gia?", "a": "Là sự nghiệp của toàn dân, lực lượng Công an nhân dân làm nòng cốt.", "flag": false}, {"id": 356, "lesson": "Bài 11", "number": "6", "q": "Bảo vệ an ninh chính trị nội bộ được Đảng ta xác định thế nào?", "a": "Nhiệm vụ trọng yếu hàng đầu, thường xuyên, cấp bách.", "flag": false}, {"id": 357, "lesson": "Bài 11", "number": "7", "q": "Bảo vệ an ninh dân tộc là bảo vệ gì?", "a": "Bảo vệ quyền bình đẳng, sự phát triển chung theo pháp luật của các dân tộc, đấu tranh chống chia rẽ dân tộc.", "flag": false}, {"id": 358, "lesson": "Bài 11", "number": "8", "q": "Bảo vệ an ninh tôn giáo là bảo vệ gì?", "a": "Bảo vệ chính sách tôn giáo, đảm bảo quyền tự do tín ngưỡng, chống các thế lực lợi dụng tôn giáo phá hoại an ninh.", "flag": false}, {"id": 359, "lesson": "Bài 11", "number": "9", "q": "Bảo vệ an ninh văn hóa, tư tưởng ở ta là bảo vệ gì?", "a": "Bảo vệ nền tảng tư tưởng của Đảng (chủ nghĩa Mác-Lênin, tư tưởng Hồ Chí Minh), truyền thống văn hóa dân tộc.", "flag": false}, {"id": 360, "lesson": "Bài 11", "number": "10", "q": "Bảo vệ an ninh biên giới là ở ta là bảo vệ gì?", "a": "Bảo vệ an ninh, trật tự của Tổ quốc ở khu vực biên giới, cả đất liền và trên biển.", "flag": false}, {"id": 361, "lesson": "Bài 11", "number": "11", "q": "Đối tượng của Việt Nam trong tình hình mới được Đảng ta xác định thế nào?", "a": "Bất kỳ thế lực nào có âm mưu và hành động chống phá mục tiêu của nước ta trong sự nghiệp xây dựng và bảo vệ Tổ quốc.", "flag": false}, {"id": 362, "lesson": "Bài 11", "number": "12", "q": "Đối tác của Việt Nam trong tình hình mới được Đảng ta xác định thế nào?", "a": "Những ai chủ trương tôn trọng độc lập, chủ quyền, thiết lập và mở rộng quan hệ hữu nghị, hợp tác bình đẳng, cùng có lợi.", "flag": false}, {"id": 363, "lesson": "Bài 11", "number": "13", "q": "Đối tượng bảo vệ của công tác bảo vệ an ninh chính trị gồm nội dung nào sau đây?", "a": "Cương lĩnh, Điều lệ Đảng, Hiến pháp, Pháp luật, nền tảng tư tưởng Mác - Lênin, tư tưởng Hồ Chí Minh và cán bộ, đảng viên.", "flag": false}, {"id": 364, "lesson": "Bài 11", "number": "14", "q": "Đối tượng bảo vệ của công tác bảo vệ an ninh chính trị nội bộ?", "a": "Đảng, Nhà nước, cán bộ, đảng viên, bảo vệ bí mật nhà nước.", "flag": false}, {"id": 365, "lesson": "Bài 11", "number": "15", "q": "Mục đích của công tác bảo vệ an ninh chính trị nội bộ là bảo vệ gì?", "a": "Bảo vệ Cương lĩnh, Điều lệ Đảng, bảo vệ Hiến pháp và Pháp luật, ngăn chặn suy thoái tư tưởng chính trị.", "flag": false}, {"id": 366, "lesson": "Bài 11", "number": "16", "q": "Bảo vệ an ninh chính trị, kinh tế, văn hóa tư tưởng; lực lượng nào xác định là lực lượng nòng cốt?", "a": "Lực lượng Công an nhân dân.", "flag": false}, {"id": 367, "lesson": "Bài 11", "number": "17", "q": "Chủ thể trực tiếp, lực lượng nòng cốt trong bảo vệ an ninh, trật tự là lực lượng nào?", "a": "Lực lượng Công an nhân dân.", "flag": false}, {"id": 368, "lesson": "Bài 11", "number": "18", "q": "Trật tự, an toàn xã hội là?", "a": "Trạng thái xã hội có kỷ cương, an toàn, ổn định được duy trì bởi quy phạm pháp luật và quy phạm đạo đức.", "flag": false}, {"id": 369, "lesson": "Bài 11", "number": "19", "q": "Bảo đảm Trật tự an toàn xã hội là?", "a": "Sử dụng các hình thức, biện pháp phòng ngừa, phát hiện, xử lý các hành vi vi phạm pháp luật về trật tự an toàn xã hội.", "flag": false}, {"id": 370, "lesson": "Bài 11", "number": "20", "q": "Trong các lĩnh vực an ninh quốc gia sau đây, lĩnh vực nào được xác định là cốt lõi, xuyên suốt nhất?", "a": "An ninh chính trị (đặc biệt là An ninh chính trị nội bộ).", "flag": false}, {"id": 371, "lesson": "Bài 11", "number": "21", "q": "Lực lượng nào chuyên trách bảo vệ an ninh trên biển của nước ta hiện nay?", "a": "Cảnh sát biển, Hải quân, Kiểm ngư và Công an/Biên phòng biển.", "flag": false}, {"id": 372, "lesson": "Bài 11", "number": "22", "q": "Bảo vệ môi trường là một trong những nội dung của công tác:", "a": "Bảo đảm trật tự an toàn xã hội / An ninh phi truyền thống.", "flag": true}, {"id": 373, "lesson": "Bài 11", "number": "23", "q": "Để bảo đảm thắng lợi hoàn toàn và triệt để trong cuộc đấu tranh bảo vệ ANQG, TTATXH, lực lượng công an phải:", "a": "Dựa vào nhân dân, phát huy sức mạnh tổng hợp của cả hệ thống chính trị.", "flag": false}, {"id": 374, "lesson": "Bài 11", "number": "24", "q": "Một trong những quan điểm của Đảng, Nhà nước trong công tác bảo vệ an ninh quốc gia, trật tự, an toàn xã hội là:", "a": "Đặt dưới sự lãnh đạo tuyệt đối, trực tiếp về mọi mặt của Đảng, sự quản lý của Nhà nước.", "flag": false}, {"id": 375, "lesson": "Bài 11", "number": "25", "q": "Mối quan hệ giữa bảo vệ an ninh quốc gia và giữ gìn trật tự, an toàn xã hội là:", "a": "Mối quan hệ khăng khít, tác động qua lại lẫn nhau; ANQG giữ vai trò quyết định, TTATXH tạo tiền đề ổn định.", "flag": false}, {"id": 376, "lesson": "Bài 11", "number": "26", "q": "Nội dung nào thể hiện quan điểm của Đảng, Nhà nước ta trong bảo vệ an ninh quốc gia, trật tự, an toàn xã hội?", "a": "Kết hợp chặt chẽ giữa chủ động phòng ngừa với chủ động tiến công, lấy phòng ngừa giữ vững bên trong là chính.", "flag": false}, {"id": 377, "lesson": "Bài 11", "number": "27", "q": "Một trong những nội dung giữ gìn trật tự an toàn xã hội là :", "a": "Phòng, chống tội phạm và vi phạm pháp luật về trật tự an toàn xã hội; bảo đảm trật tự an toàn giao thông, PCCC.", "flag": false}, {"id": 378, "lesson": "Bài 11", "number": "28", "q": "Nội dung nào thể hiện quan điểm của Đảng, Nhà nước ta trong bảo vệ an ninh quốc gia, giữ gìn trật tự an toàn xã hội?", "a": "Quán triệt tư tưởng lấy dân làm gốc, phát huy sức mạnh đại đoàn kết toàn dân.", "flag": false}, {"id": 379, "lesson": "Bài 11", "number": "29", "q": "Đảng lãnh đạo trực tiếp về mọi mặt là nhân tố quyết định thắng lợi của cuộc đấu tranh bảo vệ ANQG và TTATXH là:", "a": "Quan điểm, nguyên tắc chỉ đạo của Đảng trong bảo vệ ANQG và TTATXH.", "flag": false}, {"id": 380, "lesson": "Bài 11", "number": "30", "q": "Bảo vệ sự ổn định, phát triển vững mạnh của nền kinh tế thị trường nhiều thành phần theo định hướng XHCN là:", "a": "Bảo vệ an ninh kinh tế.", "flag": false}, {"id": 381, "lesson": "Bài 11", "number": "31", "q": "Phòng ngừa tai nạn lao động, phòng chống thiên tai, dịch bệnh là một trong những nội dung của:", "a": "Giữ gìn trật tự, an toàn xã hội / Bảo đảm an ninh xã hội.", "flag": true}, {"id": 382, "lesson": "Bài 11", "number": "32", "q": "Đối tượng xâm phạm đến an ninh quốc gia trong tình hình hiện nay là:", "a": "Các thế lực thù địch, các tổ chức/cá nhân phản động, gián điệp, đối tượng vi phạm an ninh mạng.", "flag": false}, {"id": 383, "lesson": "Bài 11", "number": "33", "q": "Đâu là lực lượng phản động?", "a": "Các tổ chức, cá nhân có hành vi chống đối Đảng, Nhà nước, âm mưu lật đổ chính quyền nhân dân.", "flag": false}, {"id": 384, "lesson": "Bài 11", "number": "34", "q": "Đâu không phải là đối tượng xâm phạm về trật tự an toàn xã hội?", "a": "Các đối tượng chấp hành nghiêm chỉnh quy định pháp luật và trật tự công cộng.", "flag": false}, {"id": 385, "lesson": "Bài 11", "number": "35", "q": "Đâu không phải nội dung bảo đảm trật tự an toàn xã hội?", "a": "Các nội dung không thuộc phạm vi phòng chống tội phạm, trật tự giao thông, PCCC, bảo vệ môi trường.", "flag": false}, {"id": 386, "lesson": "Bài 11", "number": "36", "q": "Hiến pháp 2013 của nước Cộng hòa xã hội chủ nghĩa Việt Nam khẳng định bảo vệ Tổ quốc là?", "a": "Nghĩa vụ thiêng liêng và quyền cao quý của mọi công dân.", "flag": false}];